WITH payload AS (SELECT $archive_payload$[{"id":"140d0f98-e9b8-501c-bfa3-1a75997d6026","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -املطالبة بفسخ عقد البيع لعدم تنفيذ بنوده -شرط فك رهن العقار -عقد البيع عقد الزم ال يجوز فسخه إال برضا الطرفني -وجوب الوفاء بالعقود -اليمن بعد احلكم ال تسقط بعدم طلبها قبله -احلكم برد دعوى املدعي وأن ملكية العقار للمدعى عليه - التهميش على الصك بانتقال امللكية يكون بعد اكتساب احلكم القطعية بالتصديق عليه من محكمة الاستئناف .","document_number":"34304304","case_number":"34157085","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة عيون اجلواء املنتدب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/23","year":"1434","subject":"بيع -املطالبة بفسخ عقد البيع لعدم تنفيذ بنوده -شرط فك رهن العقار -عقد البيع عقد الزم ال يجوز فسخه إال برضا الطرفني -وجوب الوفاء بالعقود -اليمن بعد احلكم ال تسقط بعدم طلبها قبله -احلكم برد دعوى املدعي وأن ملكية العقار للمدعى عليه - التهميش على الصك بانتقال امللكية يكون بعد اكتساب احلكم القطعية بالتصديق عليه من محكمة الاستئناف .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/23 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34304304 :‬‬\n                    ‫َر ْق ُم الدعوى‪34157085 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 35106875‬تاريخه‪1435/1/7 :‬هـ‬\n\n\n‫بيــع ‪ -‬املطالبــة بفســخ عقــد البيــع لعــدم تنفيــذ بنــوده ‪ -‬شــرط فــك‬\n‫رهــن العقــار ‪ -‬عقــد البيــع عقــد الزم ال يجــوز فســخه إال برضا الطرفني‬\n‫‪ -‬وجــوب الوفــاء بالعقــود ‪ -‬اليمــن بعــد احلكــم ال تســقط بعــدم طلبهــا‬\n‫قبلــه ‪ -‬احلكــم بــرد دعــوى املدعــي وأن ملكيــة العقــار للمدعــى عليــه ‪-‬‬\n‫التهميــش علــى الصــك بانتقــال امللكيــة يكــون بعــد اكتســاب احلكــم‬\n                ‫القطعيــة بالتصديــق عليــه مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n                  ‫‪ .1‬قوله تعالى ( يا أيها الذين آمنوا أوفوا بالعقود) ‪.‬‬\n       ‫‪ .2‬املادة‪ 2/166‬من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه وكل املدعــى عليــه لينهــي وضــع‬\n‫منزلــه وفــك الرهــن العقــاري وإبــراء ذمتــه مــن صنــدوق التنميــة العقــاري‬\n‫الواقــع يف ‪...‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل ومــن‬\n‫ضمــن الوكالــة علــى مبلــغ يف حســابه وقــدره مائة ألف ريــال فيما يخص‬\n‫موضــع املنــزل وقــد باعــه هــذا املنــزل علــى أنــه يفــك الرهــن خــال ســنة‬\n‫مــن تاريــخ املبايعــة إال أنــه لــم يفــك الرهــن حتــى هــذه اللحظــة ويطلــب‬\n‫فســخ هــذه املبايعــة هكــذا ادعــى ‪ ،‬أجــاب املدعــى عليــه بــأن معــه‬\n\n                                                                                    ‫‪174‬‬\n\f      ‫مــا يثبــت مبايعــة العقــار لــه بإقــرار مــن املدعــي وشــهود‪ ،‬وقــام املدعــي‬\n      ‫بعمــل صــك وكالــة بذلــك بــدون قيــود وشــروط وأنــه جــدد الرخصــة‬\n      ‫مــن البلديــة وكذلــك معــه إيصــاالت تثبــت أنــه قــام بتســديد بعــض‬\n      ‫األقســاط وأنكــر أن املدعــى اشــترط فــك الرهــن خــال ســنة ويطلــب‬\n      ‫نقــل العقــار باســمه ‪ ،‬قــرر الطرفــان بــأن الصــك مرهــون حــن البيــع لدى‬\n      ‫صنــدوق التنميــة العقــاري ‪ ،‬ال بينــة للمدعــي علــى أنــه اشــترط مــدة ســنة‬\n      ‫للمدعــى عليــه لفــك الرهــن جــرى إفهــام املدعــي بــأن لــه ميــن املدعــى‬\n      ‫عليــه علــى نفــي الشــرط فلــم يقبــل بيمينــه ‪ ،‬أفــاد صنــدوق التنميــة بفــك‬\n      ‫ا ‪ ،‬وملــا كان املدعــي يطلــب‬      ‫الرهــن عــن الصــك لســداد القــرض كامـ ً‬\n      ‫احلكــم بفســخ عقــد بيــع منزلــه املوصــوف يف دعــواه إلخــال املدعــى‬\n      ‫عليــه بشــرط فــك رهنــه لــدى صنــدوق التنميــة العقــاري خــال ســنة‬\n      ‫مــن تاريــخ املبايعــة وملــا كان املدعــى عليــه منكــر ًا لهــذا الشــرط وال‬\n      ‫بينــة لــدى املدعــي تثبتــه وقــد جــرى إفهامــه أن لــه ميــن خصمــه املدعــى‬\n      ‫عليــه فلــم يطلبهــا وملــا كان عقــد البيــع هــو عقــد الزم ال يجــوز فســخه‬\n      ‫إال برضــا الطرفــن املتعاقديــن وحيــث لــم يــرض بذلــك املدعــى عليــه‬\n      ‫بصفتــه مشــتريا وقــد قــال اهلل عــز وجــل‪( :‬يــا أيهــا الذيــن آمنــوا أوفــوا‬\n      ‫بالعقــود) وطلــب إثبــات ملكيتــه للعقــار محــل الدعــوى ونقلهــا لــه وحيــث‬\n      ‫إن املرتهــن وهــو صنــدوق التنميــة العقــاري أفــاد بــأن الرهــن قــد فــك عــن‬\n      ‫هــذا العقــار ولــم يعــد للصنــدوق عالقــة بــه وبعــد التأكــد مــن ســريان‬\n      ‫مفعــول الصــك وصالحيتــه لالعتمــاد عليــه عنــد اإلفــراغ ‪ ،‬ملــا تقــدم‬\n      ‫احلكــم مبــا يلــي‪ :‬بــرد دعــوى املدعــي ضــد املدعــى عليــه وللمدعــي طلــب‬\n      ‫ميــن املدعــى عليــه علــى نفــي الشــرط املدعــى بــه متــى شــاء ثانيــا‪ :‬ثبــت أن‬\n      ‫املدعــي قــد بــاع عقــاره املوصــوف يف دعــواه علــى املدعــى عليــه وأن هــذا‬\n\n\n‫‪175‬‬\n\f‫العقــار قــد صــارت ملكيتــه للمدعــى عليــه ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n‫واعتــرض املدعــي بالئحــة ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة األولــى‬\n                                   ‫مبحكمــة االســتئناف مبنطقــة القصيــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬قاضي احملكمة العامة مبحافظة‬\n‫عيون اجلواء املنتدب وبناء على املعاملة املقيدة لدينا برقم ‪34833195‬‬\n‫وتاريــخ ‪ 1434/04/06‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/05/25‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .......‬وادعــى علــى احلاضــر معــه ‪......‬‬\n‫‪.‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪.......‬قائــا يف دعــواه عليــه‪:‬‬\n‫لقــد وكلــت املدعــى عليــه أن ينهــي وضــع منزلــي وفــك الرهــن العقــاري‬\n‫وإبــراء ذمتــي مــن صنــدوق التنميــة العقاريــة الواقــع يف ‪...‬مبوجــب الصــك‬\n‫الصادر من محكمة ‪...‬برقم ‪ 102‬يف ‪1402/10/7‬هـ واحملدودة شــماال‬\n‫القطعــة رقــم ‪ 155‬بطــول عشــرين متــر ًا وجنوبــا القطعــة رقــم ‪ 151‬بطــول‬\n‫عشــرين متــرا وشــرقا شــارع عــرض ‪15‬م بطــول عشــرين متــرا وغربــا‬\n‫القطعــة رقــم ‪ 154‬بطــول عشــرين متــرا واملســاحة اإلجماليــة أربعمائــة‬\n‫متــر مربــع وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل قصيبــاء‬\n‫برقــم ‪ 1/115‬يف ‪1415/9/13‬ه ـ ومــن ضمــن الوكالــة علــى مبلــغ يف‬\n‫حســابي وقــدره مائــة ألــف ريــال فيمــا يخــص موضــع املنــزل وقــد بعتــه‬\n‫هــذا املنــزل علــى أنــه يفــك الرهــن ســنة مــن تاريــخ املبايعــة إال أنــه لــم يفــك‬\n‫الرهــن حتــى هــذه اللحظــة وأنــا اآلن أطالــب بإعــادة بيعتــي املذكــورة‬\n‫أعــاه لــي حــاال وفســخ هــذه املبايعــة هــذه دعــواي وبعرضــه علــى املدعــى‬\n\n                                                                                              ‫‪176‬‬\n\f      ‫عليــه أجــاب قائــا‪ :‬أطلــب مهلــة للجــواب ورفعــت اجللســة بنــاء علــى طلبــه‬\n                     ‫إلــى يــوم األحــد ‪1434/6/11‬ه ـ الســاعة العاشــرة والنصــف‬\n      ‫ثــم يف يــوم األحــد املوافق‪1434/06/11‬ه ـ افتتحــت اجللســة الثانيــة‬\n      ‫الســاعة احلاديــة عشــرة وخمــس عشــرة دقيقــة وفيهــا حضــر املدعــي‬\n      ‫‪.......‬يحمــل الســجل املدنــي رقــم ‪.......‬املدعــى عليــه ‪.......‬فلــم يحضــر‬\n      ‫وقــد انتهــى وقــت اجللســة وزيــادة دون حضــوره وال مــن ميثلــه بوكالــة‬\n      ‫شــرعية ولــم يقــدم عــذر ًا مقبــو ًال أوغيــر مقبــول لــذا واحلــال مــا ذكــر‬\n      ‫فقــد قــررت رفــع اجللســة إلحضــاره مــرة أخــرى يف يــوم االحــد املوافــق‬\n      ‫‪1434/7/16‬ه ـ الســاعة التاســعة‪ .‬احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬‬\n      ‫رئيــس احملكمــة العامــة يف عيــون اجلــواء وبنــاء علــى قــرار معالــي وزيــر‬\n      ‫العــدل رقــم ‪ 10641‬وتاريــخ ‪1434/4/21‬ه ـ املبنــي علــى قــرار املجلــس‬\n      ‫األعلــى للقضــاء رقــم ‪ 34 / 1 / 91‬وتاريــخ ‪1434/4/17‬ه ـ املتضمــن‬\n      ‫نقلــي لقضــاء احملكمــة العامــة يف عيــون اجلــواء ففــي يــوم االحــد املوافــق‬\n      ‫‪1434/7/16‬ه ـ افتتحــت اجللســة الثالثــة الســاعة العاشــرة والنصــف‬\n      ‫صباحـ ًا وفيهــا حضــر املدعــي واملدعــى عليــه ثــم جــرى تطبيــق املــادة ‪166‬‬\n      ‫‪ 2 /‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وتــاوة مــا ســبق‬\n      ‫ضبطــه علــى املترافعــن فلمــا ســمعاه قــررا بقولهمــا نصــادق علــى مــا‬\n      ‫ضبــط يف اجللســة الســابقة هكــذا قــررا ثــم ســألت املدعــى عليــه اجلــواب‬\n      ‫عــن دعــوى املدعــي والــذي وعــد باحضــاره يف اجللســة االولــى املؤرخــة يف‬\n      ‫‪1434/5/25‬ه ـ فأبــرز ورقــة محــرره هــذا نصهــا‪« :‬معــي مايثبــت مبايعــة‬\n      ‫العقــار لــي بإقــرار منــه وشــهود وكذلــك املقــاول الــذي اختلــف معــه‬\n      ‫بســبب العقــار (عظــم لــم يكتمــل العظــم البنــاء) وكذلــك بعــد فتــرة‬\n      ‫بلغــت املدعــي بــأن العقــار شــبه انتهــى وأريــد ســحب الدفعــات الباقيــة‬\n\n\n‫‪177‬‬\n\f‫إلنهــاء التشــطيبات األخيــرة وأنــزل ببيتــي الــذي أشــتريته منــه بأربعــن‬\n‫ألــف ريــال ســعودي وقــام املدعــو ‪ ...‬بعمــل صــك وكالــة بذلــك وإقــرار‬\n‫مبراجعــة البنــك العقــاري واســتالم الدفعــات والتســديد والتأجيــر‬\n‫واســتالم األجــرة والتوقيــع نيابــة عنــه فيمــا يســتوجب حضــوره وكل‬\n‫الزمــن متفقــن وبــدون قيــود وشــروط وقــد جــددت الرخصــة مــن البلديــة‬\n‫ومعــي إيصــال علــى ذلــك وكذلــك معــي إيصــاالت تثبــت أننــي قمــت‬\n‫بتســديد بعــض األقســاط وأطلــب مــن اهلل ثــم منكــم إنهــاء الدعــوة بينــي‬\n‫وبينــه بنقــل العقــار باســمي‪ )...‬هــذا مــا أبــرزه املدعــى عليــه ثــم ســألت‬\n‫الطرفــن هــل كان الصــك مرهونــا حــن البيــع لــدى صنــدوق التنميــة‬\n‫العقاريــة؟ فأجابــا قائلــن‪ :‬نعــم كان مرهونــا هكــذا أجابــا ثــم ســألت‬\n‫املدعــي هــل مت كتابــة عقــد مبايعــة بينــه وبــن املدعــى عليــه؟ فأجــاب‬\n‫قائــا‪ :‬ال لــم يتــم ذلــك هكــذا أجــاب ثــم ســألته أيضـ ًا عــن تاريــخ املبايعــة‬\n‫فأجــاب قائــا‪ :‬إنــه مت قبــل أربعــن ســنة هكــذا أجــاب ثــم ســألته هــل‬\n‫لديــه بينــة علــى أنــه أشــترط علــى املدعــى عليــه أن يفــك رهــن املنــزل‬\n‫خــال ســنة مــن تاريــخ املبايعــة؟ فأجــاب قائ ـاً‪ :‬ال بينــة لــدي هكــذا‬\n‫أجــاب وللكتابــة إلــى فضيلــة رئيــس احملكمــة العامــة يف ‪...‬لالستفســار‬\n‫عــن ســريان مفعــول الصــك املرصــود رقمــه وتاريخــه يف اجللســة األولــى‬\n‫وللكتابــة أيضــا لصنــدوق التنميــة العقاريــة بطلــب اإلفــادة عــن مــا‬\n‫لديهــم حــول مبايعــة املدعــي للمدعــى عليــه العقــار اململــوك بالصــك‬\n‫املرهــون لصاحلهــم رفعــة اجللســة وكان ختامهــا يف متــام الســاعة احلاديــة‬\n‫عشــرة والربــع صباح ـ ًا وحــددت للطرفــن موعــد ًا يف يــوم الثالثــاء‬\n‫املوافــق ‪1434/8/16‬ه ـ الســاعة العاشــرة صباح ـ ًا ثــم يف يــوم الثالثــاء‬\n‫املوافــق‪ 1434/08/16‬ه ـ ويف املوعــد احملــدد افتتحــت اجللســة الرابعــة‬\n\n\n                                                                                         ‫‪178‬‬\n\f      ‫وفيهــا حضــر الطرفــان املدعــي ‪.......‬واملدعــى عليــه ‪ .......‬وقــد وردنــا‬\n      ‫خطــاب فضيلــة كاتــب عــدل ‪...‬رقــم‪ 341838479‬وتاريخ‪1434/8/8‬ه ـ‬\n      ‫املتضمــن أن صــك قطعــة األرض املتنــازع عليهــا بــن الطرفــن الزال‬\n      ‫ســاري املفعــول ومطابــق لســجله كمــا وردنــا خطــاب ســعادة مديــر عــام‬\n      ‫فــرع صنــدوق التنميــة العقاريــة مبنطقــة القصيــم رقــم‪34904/7384‬‬\n      ‫يف ‪1434/8/10‬ه ـ وقــد جــاء فيــه أن العقــار اململــوك بالصــك ‪102‬‬\n      ‫وتاريخ‪1402/10/7‬ه ـ ســبق وأن اقتــرض لــه بالعقــد رقــم ‪5847/3/6‬‬\n      ‫وتاريخ‪1409/8/28‬ه ـ وقــد ســدد كامــل القــرض وقــدره مائتــا ألــف‬\n      ‫ريــال بتاريــخ ‪1433/1/8‬ه ـ وبذلــك يتضــح أن العقــار قــد فــك الرهــن‬\n      ‫عنــه وال عالقــة للصنــدوق بــه بعــد ذلــك هــذا ماتضمنــه خطــاب صنــدوق‬\n      ‫التنميــة العقاريــة وملــا كان املدعــي يطلــب فســخ بيــع عقــاره اململــوك‬\n      ‫بالصــك املشــار لــه أعــاه بســبب أنــه اشــترط علــى املشــتري وهــو املدعــى‬\n      ‫عليــه هنــا أن يفــك الرهــن يف مهلــة ســنة مــن تاريــخ املبايعــة التــي كانــت‬\n      ‫قبــل أربعــن ســنة علــى حســب دعــواه فحيــث وردنــا مــن صنــدوق التنميــة‬\n      ‫العقاريــة أن العقــار قــد فــك الرهــن عنــه بتاريــخ ‪1433/1/8‬ه ـ وحيــث‬\n      ‫البينــة للمدعــي حســب مــا أفــاد بــه يف اجللســة املاضية وقــد أفهمته بأن له‬\n      ‫ميــن خصمــه أنــه لــم يشــترط عليــه هــذا الشــرط ففهــم ذلك ثم قــرر قائال‬\n      ‫إننــي ال أرغــب ميــن املدعــى عليــه هكــذا قــرر وللتأمــل وإصــدار احلكــم‬\n      ‫رفعــت اجللســة يف متــام الســاعة احلاديــة عشــرة والنصــف صباحــا وحــددت‬\n      ‫للطرفــن موعــدا يف يــوم األحــد املوافــق ‪1434/8/21‬ه ـ الســاعة احلادية‬\n      ‫عشــرة والنصــف صباحــا‪ ،‬ثــم يف يــوم األحــد املوافــق‪ 1434/08/21‬ه ـ‬\n      ‫ويف املوعــد احملــدد افتتحــت اجللســة اخلامســة وفيهــا حضــر الطرفــان ثــم‬\n      ‫ســألت املدعــى عليــه هــل اشــترط عليــه املدعــي فــك رهــن منزلــه خــال‬\n\n\n‫‪179‬‬\n\f‫ســنة مــن تاريــخ املبايعــة أم ال ؟ فأجــاب قائــا‪ :‬ال لــم يشــترط ‪ ...‬ذلــك‬\n‫هكــذا أجــاب وبدراســة القضيــة وتأملهــا ملــا كان املدعــي يطلــب يف‬\n‫دعــواه هــذه احلكــم بفســخ عقــد بيــع منزلــه املوصــوف يف دعــواه والــذي‬\n‫باعــه علــى املدعــى عليــه إلخاللــه بشــرط فــك رهنــه لــدى صنــدوق‬\n‫التنميــة العقاريــة خــال ســنة مــن تاريــخ املبايعــة وملــا كان املدعــى عليــه‬\n‫منكــرا لهــذا الشــرط وال بينــة لــدى املدعــي تثبتــه وقــد جــرى إفهامــه‬\n‫أن لــه ميــن خصمــه املدعــى عليــه فلــم يطلبهــا وملــا كان عقــد البيــع هــو‬\n‫عقــد الزم ال يجــوز فســخه إال برضــى الطرفــن املتعاقديــن وحيــث لــم‬\n‫يــرض بذلــك املدعــى عليــه بصفتــه مشــتريا وقــد قــال اهلل عــز وجــل‪( :‬يــا‬\n‫أيهــا الذيــن آمنــوا أوفــوا بالعقــود) وطلــب إثبــات ملكيتــه للعقــار محــل‬\n‫الدعــوى ونقلهــا لــه وحيــث إن املرتهــن وهــو صنــدوق التنميــة العقاريــة‬\n‫أفــاد بــأن الرهــن قــد فــك عــن هــذا العقــار ولــم يعــد للصنــدوق عالقــة‬\n‫بــه وبعــد التأكــد مــن ســريان مفعــول الصــك وصالحيتــه لالعتمــاد‬\n‫عليــه عنــد اإلفــراغ فقــد صــدر منــي مــا يلــي أوال‪ :‬حكمــت بــرد دعــوى‬\n‫املدعــي ‪.......‬ضــد املدعــى عليــه ‪.......‬وللمدعــي طلــب ميــن املدعــى عليــه‬\n‫علــى نفــي الشــرط املدعــى بــه متــى شــاء ثانيــا‪ :‬ثبــت لــدي أن املدعــي‬\n‫قــد بــاع عقــاره املوصــوف يف دعــواه علــى املدعــى عليــه وأن هــذا العقــار‬\n‫قــد صــارت ملكيتــه للمدعــى عليــه وبذلــك حكمــت وبإعــان احلكــم‬\n‫للطرفــن قــرر املدعــي عــدم القناعــة وطلــب التمييــز بالئحــة اعتراضيــة‬\n‫فافهمتــه مبراجعــة احملكمــة يــوم اإلربعــاء القــادم بــإذن اهلل املوافــق‬\n‫‪1434/8/24‬ه ـ الســتالم نســخة احلكــم وتقــدمي اعتراضــه عليــه خــال‬\n‫املــدة املقــررة لالعتــراض وهــي ثالثــون يومــا مــن تاريــخ املوعــد احملــدد‬\n‫لالســتالم فــان لــم يتقــدم باعتراضــه خاللهــا ســقط حقــه يف التمييــز‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫واكتســب احلكــم الصفــة القطعيــة ففهــم ذلــك ‪ ،‬وأمــا املدعــى عليــه‬\n      ‫فقــرر القناعــة باحلكــم فأفهــم بــأن التهميــش بانتقــال امللكيــة إمنــا‬\n      ‫يكــون بعــد اكتســاب هــذا احلكــم القطعيــة ففهــم ذلــك‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪ 1434/08/21‬ه ـ ‪.‬‬\n\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 35106875‬وتاريــخ‬\n                                                        ‫‪1435/1/7‬هـ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":174,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a9000b461348bbb99eebee26eae9589ca4cfc69a55923dabf121ce78b166ffd9","normalized_text_hash":"98bb7158f1f747de005d42bce3e90337efd5027abcc828ca2ee1e736af021e27","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p174-34304304"},{"id":"80759d2c-58c8-5d09-970c-5c0795cf9065","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع أطقم ذهب مرصعة باألملاس باآلجل -دفع جزء من الثمن واملطالبة بباقي الثمن -الدفع بإقامة الدعوى على غير ذي صفة -الدفع بعدم اإلختصاص احمللي والوالئي -الرد على الدفعن وانعقاد اإلختصاص للمحكمة -القضاء بالشاهد واليمن -إلزام املدعى عليه بدفع املبلغ املتبقي للمدعى .","document_number":"34167660","case_number":"32321645","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"بيع -بيع أطقم ذهب مرصعة باألملاس باآلجل -دفع جزء من الثمن واملطالبة بباقي الثمن -الدفع بإقامة الدعوى على غير ذي صفة -الدفع بعدم اإلختصاص احمللي والوالئي -الرد على الدفعن وانعقاد اإلختصاص للمحكمة -القضاء بالشاهد واليمن -إلزام املدعى عليه بدفع املبلغ املتبقي للمدعى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/21 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34167660 :‬‬\n                    ‫َر ْق ُم الدعوى‪32321645 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34230665‬تاريخه‪1434/6/5 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع أطقــم ذهــب مرصعــة باألملــاس باآلجل ‪ -‬دفع جزء من الثمن‬\n‫واملطالبــة بباقــي الثمــن ‪ -‬الدفــع بإقامــة الدعــوى علــى غيــر ذي صفــة‬\n‫‪ -‬الدفــع بعــدم اإلختصــاص احمللــي والوالئــي ‪ -‬الــرد علــى الدفعــن‬\n‫وانعقــاد اإلختصــاص للمحكمــة ‪ -‬القضــاء بالشــاهد واليمــن‪ -‬إلــزام‬\n                          ‫املدعــى عليــه بدفــع املبلــغ املتبقــي للمدعــى ‪.‬‬\n\n\n\n\n‫‪ .1‬عــن ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه‬\n                ‫وســلم قضــى باليمــن مــع الشــاهد رواه أحمــد وغيــره‪.‬‬\n‫‪ .2‬مــا ذكــره صاحــب الــروض املربــع‪( :‬ويقبــل يف املــال ومــا يقصــد بــه‬\n‫املــال كالبيــع واألجــل واخليــار فيــه أي يف البيــع ونحــوه ‪ ...‬رجــل وميــن‬\n                                                                     ‫املدعــي) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه بــاع للمدعــى عليــه قبــل خمســة أعــوام تقريب ـ ًا‬\n‫ثالثــة أطقــم ذهــب مرصعــة باألملــاس بشــرط أن تنــال األطقــم رضــاه‬\n‫بثمــن قــدره ثمامنائــة وخمســون ألــف ريــال ‪ ،‬دفــع املدعــى عليــه ثالثمائــة‬\n‫وخمســن ألــف ريــال ولــم يعــد مــن تلــك األطقــم شــيئ ًا وهــذا دليــل علــى‬\n‫رضــاه باملبيــع وتبقــى يف ذمتــه خمســمائة ألــف ريــال ‪ ،‬طلــب إلــزام‬\n\n                                                                                    ‫‪182‬‬\n\f      ‫املدعــى عليــه بســدادها ‪ ،‬دفــع املدعــى عليــه بــأن هــذه الدعــوى مقامــة‬\n      ‫علــى غيــر ذي صفــة ألن املبلــغ يف ذمــة مؤسســة ال ميلكهــا املدعــى عليــه‬\n      ‫وطلــب رد الدعــوى ‪ ،‬أفهــم املدعــى عليــه بــأن عليــه الــرد علــى دعــوى‬\n      ‫املدعــي وعــدم االكتفــاء بالــرد علــى الطلــب ‪ ،‬طلــب مهلــة لذلــك ‪ ،‬افهــم‬\n      ‫بأنهــا املهلــة األخيــرة وإال ســيعد نــكا ًال عــن اجلــواب ‪ ،‬احضــر املدعــي‬\n      ‫شــاهد ًا وشــهد بــأن املدعــى عليــه أقــر أمامــه بــأن يف ذمتــه للمدعــي‬\n      ‫املبلــغ املدعــى بــه ‪ ،‬أحضــر املدعــى عليــه وكالــة خطاب ـ ًا مــن والــد‬\n      ‫موكلــه بصفتــه صاحــب املؤسســة املذكــورة يتضمــن أن مؤسســته هــي‬\n      ‫املشــترية لألطقــم وأنهــا اثنــان وليســت ثالثــة وأن قيمتهــا ســبعمائة ألــف‬\n      ‫ريــال وذكــر املبلــغ املســتلم واملبلــغ املتبقــي ‪ ،‬ذكــر املدعــى عليــه بــأن‬\n      ‫الشــاهد شــريك للمدعــي ويعمــل معــه‪ ،‬أنكــر املدعــي ذلــك ‪ ،‬ذكــر‬\n      ‫املدعــى بــأن املدعــى عليــه لــم يجــب علــى الدعــوى وأن خطــاب املؤسســة‬\n      ‫املذكــورة ال عالقــة لــه مبوضــوع الدعــوى ‪ ،‬دفــع املدعــى عليــه بدفــع‬\n      ‫شــكلي وهــو عــدم اختصــاص احملكمــة املكانــي والوالئــي ‪ ،‬جــرى رد‬\n      ‫هــذا الدفــع مــن قبــل احملكمــة وبيــان انعقــاد االختصــاص للمحكمــة ‪،‬‬\n      ‫جــرى تعديــل الشــاهد‪ ،‬طلــب مــن املدعــي أصالــة اليمــن ‪ ،‬حلــف املدعــي‬\n      ‫اليمــن ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n      ‫للمدعــي‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪183‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة (‪ )....‬املســاعد برقــم ‪32321645‬‬\n‫وتاريــخ ‪1433/04/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32977817‬وتاريــخ‬\n‫‪1432/08/02‬ه ـ ففــي يــوم األحــد املوافق‪1434/01/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر (‪ )....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )....‬بصفتــه وكيــا عــن (‪ )....‬ســوري اجلنســية‬\n‫مبوجــب اإلقامــة رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة شــمال محافظــة جــدة برقــم ‪ 65976‬وتاريــخ ‪1432/7/18‬ه ـ‬\n‫جلــد ‪1432/7/18‬ه ـ ‪،‬وادعــى علــى احلاضــر معــه (‪ )....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬بصفتــه وكيــا عــن (‪ )....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬مبوجــب الوكالــة رقــم‬\n‫‪ 19805‬تاريــخ ‪1432/6/1‬ه ـ جلــد ‪ 3387‬الصــادرة مــن كتابــة عــدل‬\n‫الثانيــة بجنــوب جــدة بصفتــه وكيــا عــن املدعــى عليــه ‪...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬مبوجــب الوكالــة رقــم ‪877‬‬\n‫تاريــخ ‪1429/1/10‬ه ـ جلــد ‪ 2014‬الصــادرة مــن كتابــة عــدل الثانيــة‬\n‫بجنــوب جــدة ‪ ،‬قائــا ‪ :‬لقــد بــاع موكلــي علــى املدعــى عليــه قبــل حوالــي‬\n‫خمســة أعــوام ثالثــة أطقــم مــن الذهــب مرصعــة باألملــاس بشــرط أن تنال‬\n‫األطقــم رضــاه بثمــن قــدره ثمامنائــة وخمســون ألــف ريــال ‪ ،‬وال يذكــر‬\n‫موكلــي ثمــن كل طقــم علــى حــده ‪ ،‬ودفــع املدعــى عليــه مــن الثمــن‬\n‫مبلغــا قــدره ثالثمائــة وخمســون ألــف ريــال ‪ ،‬ولــم يعــد مــن تلــك األطقــم‬\n\n                                                                                    ‫‪184‬‬\n\f      ‫شــيئا ‪ ،‬وهــذا دليــل علــى رضــاه باملبيــع ‪ ،‬وتبقــى يف ذمــة املدعــى عليــه‬\n      ‫مــن ثمــن املبيــع مبلغــا قــدره خمســمائة ألــف ريــال ‪ ،‬أطلــب إلــزام املدعــى‬\n      ‫عليــه بدفــع املبلــغ املتبقــي وقــدره خمســمائة ألــف ريــال ‪ .‬هــذه دعــواي ‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد ‪.‬‬\n      ‫ثــم رفعــت اجللســة لذلــك ‪ .‬ويف يــوم الثالثــاء املوافــق ‪1434/03/03‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي أصالــة واملدعــي‬\n      ‫وكالــة واملدعــى عليــه وكالــة ‪ ،‬وبســؤال املدعــى عليــه وكالــة عمــا‬\n      ‫طلــب اإلمهــال مــن أجلــه قــدم مذكــرة هــذا نصهــا ‪ :‬نفيــد فضيلتكــم‬\n      ‫بخصــوص الدعــوى املقامــة مــن ‪...‬والتــي يطالــب موكلــي فيهــا مببلــغ‬\n      ‫(‪ )500,000‬خمســمائة ألــف ريــال مدعي ـ ًا بســند يف اســتحقاقه لهــذه‬\n      ‫املطالبــة ‪ .‬عليــه أفيــد فضيلتكــم أن هــذه الدعــوى مقامــة علــى غيــر ذي‬\n      ‫صفة حيث أن هذا املبلغ ال يخص موكلي وال عالقة له به ألن املطالب‬\n      ‫بــه مؤسســة ‪ ،...‬وهــو ال ميلــك هــذه املؤسســة ‪ ،‬لــذا أطلــب مــن فضيلتكم‬\n      ‫احلكــم بصــرف النظــر عــن الدعــوى وذلــك إلقامتهــا علــى غيــر ذي صفــة‬\n      ‫‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬إجابــة املدعــى عليــه وكالــة‬\n      ‫غيــر مالقيــة للدعــوى ‪ ،‬فاملدعــى عليــه هــو مــن اســتلم تلــك األطقــم ‪،‬‬\n      ‫وليــس بــن موكلــي ومؤسســة ‪...‬أي عالقــة ‪ .‬وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه وكالــة قــال ‪ :‬جوابــي علــى الدعــوى صريــح وواضــح ‪ .‬فطلبــت مــن‬\n      ‫املدعــى عليــه وكالــة الــرد علــى دعــوى املدعــي وعــدم االكتفــاء بالــرد‬\n      ‫علــى الطلــب قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬فأفهمته بأنها املــرة الثانية التي‬\n      ‫يطلــب اإلمهــال للــرد علــى دعــوى املدعــي ‪ ،‬وأنــه يف حــال عــدم إجابتــه‬\n      ‫فيعــد نــاكال عــن اإلجابــة ‪ ،‬ويقضــى عليــه بالنكــول ‪ ،‬ففهــم ذلــك ‪.‬‬\n      ‫ثــم قــرر املدعــي وكالــة قائــا ‪ :‬لــدي شــاهد أطلــب ســماع مــا لديــه ‪ .‬ثــم‬\n\n\n‫‪185‬‬\n\f‫أحضــر للشــهادة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وهــو‬\n‫مــن مواليــد ‪1385‬ه ـ ويعمــل يف جتــارة املجوهــرات يف ســوق جــدة الدولــي‬\n‫‪ ،‬وليــس بينــه وبــن طــريف الدعــوى قرابــة ‪ ،‬ويســكن يف حــي الروضــة‬\n‫‪ ،‬وشــهد قائــا ‪ :‬أشــهد بــاهلل العظيــم بأننــي قابلــت املدعــى عليــه ‪...‬قبــل‬\n‫حوالــي ثمانيــة أشــهر وأقــر أمامــي بــأن بذمتــه للمدعــي ‪...‬مبلغــا قــدره‬\n‫خمســمائة ألــف ريــال مقابــل مجوهــرات اســتلمها مــن املدعــي وهــي‬\n‫عبــارة عــن أطقــم أملــاس ‪ .‬هكــذا شــهد ‪ .‬وبعــرض الشــاهد وشــهادته‬\n‫علــى املدعــى عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬ثــم طلبــت مــن‬\n‫املدعــي وكالــة تعديــل الشــاهد فوعــد بذلــك يف اجللســة القادمــة ‪ .‬ثــم‬\n‫رفعــت اجللســة لطلــب املدعــى عليــه وكالــة الــرد علــى الدعــوى وعلــى‬\n‫الشــاهد وشــهادته ‪ .‬ويف يــوم الســبت املوافــق ‪1434/03/14‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي وكالــة ‪...‬واملدعــى‬\n‫عليــه وكالــة ‪ ،...‬وبســؤال املدعــي وكالــة عمــا وعــد بإحضــاره يف‬\n‫هــذه اجللســة أحضــر لتعديــل الشــاهد ‪...‬كال مــن ‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬و‪...‬ســوري اجلنســية مبوجــب اإلقامــة رقــم‬\n‫‪...‬وشــهد كل واحــد منهمــا بثقــة وعدالــة الشــاهد ‪ ...‬وبســؤال املدعــى‬\n‫عليــه وكالــة عمــا طلــب اإلمهــال مــن أجلــه قــال ‪ :‬لــدي خطــاب مــن والــد‬\n‫موكلــي بصفتــه صاحــب مؤسســة ‪...‬مــؤرخ يف ‪1434/3/10‬ه ـ يتضمــن‬\n‫أن موكلــي يعمــل لــدى مؤسســته وقــد اســتلم طقمــان أملــاس واتفقــا‬\n‫علــى أن يكــون الثمــن ســبعمائة ألــف ريــال ‪ ،‬بالرغــم أن قيمتهمــا ال‬\n‫تســاوي إال خمســمائة ألــف ريــال ‪ ،‬وقــد مت بيعهــا بســبعمائة ألــف ريــال‬\n‫‪ ،‬وقــد دفعــت املؤسســة للمدعــي مــن ذلــك املبلــغ مبلغــا قــدره ثالثمائــة‬\n‫وواحــد وأربعــون ألفــا وخمســمائة ريــال ‪ ،‬وبقــي بذمــة املؤسســة مبلغــا‬\n\n\n                                                                                     ‫‪186‬‬\n\f      ‫قــدره ثالثمائــة وثمانيــة وخمســون ألفــا وخمســمائة ريــال ‪ ،‬وفيمــا يخــص‬\n      ‫الشــاهد ‪ ...‬وشــهادته فإننــي أطعــن يف الشــاهد كونــه شــريكا للمدعــي‬\n      ‫ويعمــل معــه ‪ ،‬وعليــه فأطلــب احلكــم بصــرف النظــر عــن الدعــوى‬\n      ‫إلقامتهــا علــى غيــر ذي صفــة ‪ .‬ثــم أبــرز املدعــى عليــه وكالــة أصــل‬\n      ‫اخلطــاب ومرفــق بــه أربــع ورقــات كمرفقــات ‪ ،‬ومت إرفاقهــا باملعاملــة‬\n      ‫‪ ،‬وبعــرض ذلــك علــى املدعــي وكالــة قــال ‪ :‬املدعــى عليــه وكالــة لــم‬\n      ‫يجــب بجــواب مــاق ملــا طلــب منــه ‪ ،‬وفيمــا يخــص اخلطــاب فــا عالقــة‬\n      ‫للخطــاب ومــا ورد فيــه مبوضــوع الدعــوى ‪ ،‬وفيمــا يخــص الطعــن يف‬\n      ‫الشــاهد فغيــر صحيــح ‪ ،‬والشــاهد ليــس شــريكا ملوكلــي وال يعمــل‬\n      ‫معــه ‪ .‬وبســؤال املدعــى عليــه وكالــة عــن إجابتــه علــى دعــوى املدعــي‬\n      ‫وكالــة حيــث لــم يجــب عنهــا بعــد ‪ ،‬وإال فإنــه يعــد نــاكال عــن اإلجابــة‬\n      ‫وســيقضى عليــه بالنكــول قــال ‪ :‬لقــد اســتلم موكلــي طقمــي أملــاس‬\n      ‫بثمــن قــدره ســبعمائة ألــف ريــال ‪ ،‬ولكنهــا حلســاب مؤسســة ‪ ،...‬كمــا‬\n      ‫هــو موضــح يف خطــاب املؤسســة ‪ ،‬ولــم يســتلم موكلــي الطقــم الثالــث‬\n      ‫‪ ،‬وقــد ســدد مــن ثمــن الطقمــن مــا ورد يف خطــاب املؤسســة ومــا بقــي يف‬\n      ‫ذمــة املؤسســة هــو مــا ورد يف اخلطــاب أيضــا ‪ .‬وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة قــال ‪ :‬بــل الصحيــح أن تعامــل موكلــي كان مــع املدعــى عليــه‬\n      ‫بشــخصه ولــم يكــن لصالــح املؤسســة ‪ ،‬فاملطالبــة متوجــه للمدعــى‬\n      ‫عليــه دون املؤسســة ‪ .‬ثــم قــررت إدخــال مؤسســة ‪...‬للذهــب واملجوهــرات‬\n      ‫بالســجل التجــاري رقــم ‪ ،...‬وأن عــبء تبليــغ مــن ميثــل املؤسســة يقــع‬\n      ‫علــى عاتــق املدعــى عليــه وكالــة وموكلــه ‪ ،‬وأفهمتــه بــأن عليــه إبــاغ‬\n      ‫املؤسســة بالدعــوى والدفــع الــذي تقــدم بــه ‪ ،‬والبينــة علــى مــا مت ســداده‬\n      ‫مــن ثمــن األطقــم محــل الدعــوى ففهــم ذلــك ‪ .‬ثــم رفعــت اجللســة لذلــك‬\n\n\n‫‪187‬‬\n\f‫‪ .‬ويف يــوم الســبت املوافق‪1434/03/21‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 12 :‬وفيهــا حضــر املدعــي أصالــة ‪...‬ســوري اجلنســية مبوجــب اإلقامــة‬\n‫رقــم ‪ ،...‬وحضــر املدعــي وكالــة ‪ ...‬واملدعــى عليــه وكالــة ‪...‬وبصفتــه‬\n‫وكيــا عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬بصفتــه‬\n‫صاحــب مؤسســة ‪...‬للتجــارة ســجل جتــاري ‪...‬الصــادر مــن فــرع املدينــة‬\n‫املنــورة ‪ ،‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة‬\n‫املنــورة برقــم ‪ 34338604‬وتاريــخ ‪1434/3/18‬ه ـ ‪ ،‬وقــدم املدعــى عليــه‬\n                     ‫وكالــة بوكالتــه عــن املؤسســة مذكــرة هــذا نصهــا‪:‬‬\n                                                 ‫أوال ‪ :‬من الناحية الشكلية ‪:‬‬\n‫أ‪ -‬فإننــي أحصــر دفعــي الشــكلي بعــدم اختصــاص احملكمــة العامــة‬\n‫مبحافظــة جــدة محليــا بنظــر الدعــوى لوجــود املقــر الرئيســي يف (املدينــة‬\n‫املنــورة) وحيــث أن الفــرع املوجــود يف محافظــة جــدة قــد مت إغالقــه‬\n‫وشــطب ســجله التجــاري وليــس للفــرع أي مقــر يف مدينــة جــدة وبذلــك‬\n‫فــإن أي نــزاع ينشــأ ينعقــد االختصــاص بنظــره للمحكمــة املختصــة‬\n                                                    ‫مبقــر املؤسســة الرئيســي ‪.‬‬\n‫ب‪ -‬إن هــذا العمــل الــذي مت مــن بيــع طقمــي أملــاس هــو مــن األعمــال‬\n‫التجاريــة التــي تخــرج عــن اختصــاص احملكمــة العامــة وهــي مــن‬\n                                              ‫اختصــاص القضــاء التجــاري ‪.‬‬\n‫ثانيــا‪ :‬مــن الناحيــة املوضوعيــة‪ :‬املدعــى عليــه ‪...‬كان يعمــل يف فــرع‬\n‫املؤسســة التابعــة للذهــب واملجوهــرات بجــدة وقــد اســتلم مــن املدعــي‬\n‫‪...‬ســوري اجلنســية مبوجــب اإلقامــة رقــم (‪ )...‬طقمــان أملــاس اتفــق هــو‬\n‫وإيــاه أن تكــون قيمــة البيــع لهذيــن الطقمــن ســبعمائة ألــف ريــال‬\n‫(بالرغــم أن قيمتهــا ال تتجــاوز خمســمائة ألــف ريــال وقــت البيــع) حيــث‬\n\n\n                                                                                    ‫‪188‬‬\n\f      ‫أنــه مت بيعهــا مببلــغ ســبعمائة ألــف ريــال بنفــس القيمــة التــي مت شــراؤها‬\n      ‫بهــا مــن املدعــي وقــد قامــت املؤسســة بســداد مبالــغ ماليــة إجماليــة‬\n      ‫قدرهــا (‪ )341.500‬ثالثمائــة و واحــد وأربعــون ألفــا وخمســمائة ريــال‬\n      ‫وقــد أقــر املدعــي يف الئحــة دعــواه باســتالمه مبلغــا وقــدره (‪)350.000‬‬\n      ‫ثالثمائة وخمســون ألف ريال وبذلك تكون املبالغ املســلمة للمدعي إذا‬\n      ‫خصمــت مــن قيمــة االتفــاق فيكــون املبلــغ املتبقــي يف ذمة مؤسســة ‪...‬هو‬\n      ‫مبلــغ وقــدره (‪ )358.500‬ثالثمائــة وثمانيــة وخمســون ألفــا وخمســمائة‬\n      ‫ريــال ‪ .‬لــذا وملــا تقــدم نتمســك بالدفــع الشــكلي ونطلــب صــرف النظــر‬\n      ‫عــن دعــوى املدعــي لعــدم اختصــاص احملكمــة العامــة مبحافظــة جــدة‬\n      ‫محلي ـ ًا بنظــر الدعــوى ‪ .‬وبعرضــه علــى املدعــي وكالــة قــال ‪ :‬نرفــض‬\n      ‫إدخــال مؤسســة ‪ ...‬يف القضيــة وإمنــا نوجــه دعوانــا ضــد املدعــى عليــه‬\n      ‫حيــث أنــه ال يوجــد أي تعامــل أو عالقــة بــن موكلــي واملؤسســة طالبــة‬\n      ‫التداخــل يف الدعــوى ونطلــب إلــزام املدعــى عليــه بدفــع كامــل املبلــغ‬\n            ‫اســتنادا إلــى شــهادة الشــاهد و نقــرر اســتعداد موكلــي باليمــن ‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬أمتســك مبــا مت تقدميــة‬\n      ‫ســابقا ‪ .‬فأفهمــت املدعــى عليــه وكالــة بــأن حكــم املتداخــل ليــس‬\n      ‫كحكــم األصيــل يف االختصــاص املكانــي لنظــر الدعــوى ‪ ،‬كــون‬\n      ‫املدعــي وجــه دعــواه علــى املدعــى عليــه وليــس علــى املؤسســة ‪ ،‬وحيــث‬\n      ‫أقــرت املؤسســة بأمــر فــإن الدعــوى تنظــر يف هــذه احملكمــة ‪ ،‬وأمــا‬\n      ‫مــا يتعلــق بالدفــع كــون العمــل جتاريــا ‪ ،‬فــا يكــون العمــل جتاريــا إال‬\n      ‫بحســب مــا نصــت عليــه املــادة ‪ 2‬مــن نظــام احملكمــة التجاريــة ‪ ،‬ونصهــا‬\n      ‫(يعتبــر مــن األعمــال التجاريــة كل مــا هــو آت‪ :‬أ‪ -‬كل شــراء بضاعــة‬\n      ‫أو أغــال أو مأكــوالت وغيرهــا ألجــل بيعهــا بحالهــا أو بعــد صناعــة‬\n\n\n‫‪189‬‬\n\f‫وعمــل فيهــا) ‪ ،‬فعلــى املدعــى عليــه إثبــات كــون هــذا العمــل مــن قبيــل‬\n‫مــا هــو مــدرج يف هــذه الفقــرة مــن املــادة ‪ ،‬كمــا أن الدعــاوى التجاريــة‬\n‫أصبحــت مــن اختصــاص احملكمــة العامــة بصــدور نظــام القضــاء‬\n‫اجلديــد الصــادر باألمــر امللكــي ذي الرقــم م ‪78 /‬وتاريــخ ‪/9 /19‬‬\n‫‪1428‬ه ـ ‪ ،‬والــذي أوكل للمحكمــة العامــة كل مــا يتعلــق بالدعــاوى‬\n‫التجاريــة ‪ ،‬وجعــل مــن بــن الدوائــر الدائــرة التجاريــة ‪ ،‬مبوجــب املــادة‬\n‫‪/9‬د مــن نظــام القضــاء ذاتــه ‪ ،‬وعلــى ذلــك يكــون االختصــاص منعقــد‬\n‫للمحكمــة العامــة يف نظــر مثــل هــذه الدعــاوى ‪ ،‬وبعرضــه علــى املدعــى‬\n‫عليــه وكالــة قــال ‪ :‬أطلــب اإلمهــال للــرد ‪ .‬وبعــرض ذلــك علــى املدعــي‬\n‫وكالــة قــال ‪ :‬لــم تقــر املؤسســة بكامــل الدعــوى وال بكامــل املبلــغ‬\n‫‪ ،‬وقــد أقــام موكلــي البينــة علــى أن بذمــة املدعــى عليــه مبلغــا قــدره‬\n‫خمســمائة ألــف ريــال ‪ ،‬وعليــه فيكــون إقــرار املؤسســة غيــر مــاق‬\n‫للدعــوى والبينــة املقدمــة مــن قبلنــا ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وكالــة قــال ‪ :‬أمتســك مبــا ســبقت اإلشــارة لــه ‪ .‬وبعــرض اليمــن علــى‬\n‫املدعــي أصالــة علــى صحــة دعــواه وعــدم اســتالمه مــن مبلــغ الدعــوى‬\n‫شــيئا اســتعد لذلــك ‪ ،‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو‬\n‫أننــي قــد بعــت املدعــى عليــه ‪...‬قبــل حوالــي خمســة أعــوام ثالثــة أطقــم‬\n‫مــن الذهــب مرصعــة باألملــاس بشــرط أن تنــال األطقــم رضــاه ‪ ،‬بثمــن‬\n‫قــدره ثمامنائــة وخمســون ألــف ريــال ‪ ،‬ودفــع املدعــى عليــه مــن الثمــن‬\n‫مبلغــا قــدره ثالثمائــة وخمســون ألــف ريــال ‪ ،‬وتبقــى يف ذمــة املدعــى‬\n‫عليــه مــن ثمــن املبيــع مبلغــا قــدره خمســمائة ألــف ريــال ‪ ،‬ولــم يعــد مــن‬\n‫تلــك األطقــم شــيئا ‪ ،‬ولــم يســدد لــي مــن املبلــغ املتبقــي وقــدره خمســمائة‬\n‫ألــف ريــال شــيئا حتــى اليــوم ‪ .‬هكــذا حلــف ‪ .‬وبســؤال املدعــي أصالــة‬\n\n\n                                                                                      ‫‪190‬‬\n\f      ‫هــل بينــك وبــن مؤسســة ‪...‬أي تعامــل معلــق قــال ‪ :‬ال ‪ .‬فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ‪ ،‬ومبــا أن املدعــى عليــه وكالــة أنكــر‬\n      ‫دعــوى املدعــي ‪ ،‬وبنــاء علــى بينــة املدعــي علــى صحــة دعــواه واملتمثلــة‬\n      ‫يف شــهادة ‪ ...‬واملعدلــة شــرعا ‪ ،‬وبنــاء علــى أن مــا دفــع بــه املدعــى عليــه‬\n      ‫وكالــة مــن أن املســتفيد مــن تلــك األطقــم هــي مؤسســة ‪ ...‬وأنهــا طقمــن‬\n      ‫فقــط وأن ثمــن تلــك الطقمــن هــو ســبعمائة ألــف ريــال ‪ ،‬وأنكــر ذلــك‬\n      ‫املدعــي ‪ ،‬ومبــا أن إقــرار املتداخــل هــو إقــرار غيــر مــاق للدعــوى ‪،‬‬\n      ‫ومبــا أن املدعــي أنكــر وجــود تعامــات معلقــة بينــه وبــن املؤسســة‬\n      ‫‪ ،‬فــا يلــزم املدعــي بإقــرار املؤسســة علــى نفســها ‪ ،‬وبنــاء علــى ميــن‬\n      ‫املدعــي علــى صحــة دعــواه ‪ ،‬وعــدم اســتالمه مــن مبلــغ الدعــوى شــيئا ‪،‬‬\n      ‫وللحديــث املــروي عــن ابــن عبــاس ‪ :‬أن الرســول صلــى اهلل عليــه وســلم‬\n      ‫قضــى باليمــن مــع الشــاهد ‪ .‬رواه أحمــد وغيــره ‪ ،‬وملــا قــرره الفقهــاء مــن‬\n      ‫قبــول شــهادة الشــاهد الواحــد مــع ميــن املدعــي يف املــال ومــا يقصــد بــه‬\n      ‫املــال ‪ ،‬ومــن ذلــك مــا ذكــره صاحــب الــروض املربــع ونصــه ‪( :‬ويقبــل‬\n      ‫يف املــال ومــا يقصــد بــه املــال كالبيــع واألجــل واخليــار فيــه أي يف البيــع‬\n      ‫ونحــوه ‪ ..‬رجــل وميــن املدعــي) ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت علــى‬\n      ‫املدعــى عليــه ‪ ...‬بدفــع مبلــغ قــدره خمســمائة ألــف ريــال للمدعــي ‪ ....‬وبــه‬\n      ‫حكمــت ‪ .‬وبــه قنــع املدعــي وقــرر املدعــى عليــه وكالــة االعتــراض ‪،‬‬\n      ‫وجــرى تســليمه نســخة مــن احلكــم وإفهامــه بــأن لــه احلــق يف االعتــراض‬\n      ‫عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف االعتــراض ‪ ،‬واكتســب‬\n      ‫احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 12 : 40‬وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                      ‫‪1434/03/21‬ه ـ‬\n\n\n‫‪191‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي باحملكمــة العامــة بجــدة‬\n‫يف يــوم األثنــن املوافــق ‪1434/6/19‬ه ـ افتتحــت اجللســة الســاعة ‪: 15‬‬\n‫‪ 2‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب رئيســها رقــم‬\n‫‪ 32977817‬وتاريــخ ‪1434/6/11‬ه ـ وبالقــرار رقــم ‪ 34230665‬وتاريــخ‬\n‫‪1434/6/5‬ه ـ واملتضمــن مــا يلــي وبدراســة احلكــم وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم وحتــى‬\n‫ال يخفــى جــرى أثباتــه وأمــرت بأحلاقــه بصكــه وســجله وأقفلــت اجللســة‬\n‫الســاعة‪ 8 : 32‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/6/19‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ (‪ )....‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n‫‪ 34167660‬وتاريــخ ‪1434/3/21‬ه ـ املتضمــن دعــوى (‪ ( )....‬ســوري‬\n                 ‫اجلنســية ) ضــد (‪ )....‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطه والالئحــة االعتراضية تقرر باألكثرية‬\n‫املوافقــة علــى احلكــم واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                            ‫آلــه وصحبه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪192‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":182,"source_page_end":192,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a7803600cbdddd56b59283fd121b69c9f4f76866a4c170557e68fdc8971121b","normalized_text_hash":"fd1a5dd2d70b8e377fcee16bbd0c347064caaa2646f6384b09783b25f4c43561","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p182-34167660"},{"id":"339f3bea-8492-50fd-b342-f12001c94d3b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -مطالبة بإثبات بيع عقار تويف مالكه قبل إثبات بيعه وإفراغه -اثبات البيع وقبض الثمن باإلقرار وشهادة الشهود -احلكم بإثبات البيع -وجوب تدقيق احلكم لورود احلكم على قاصر .","document_number":"34203760","case_number":"34171007","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/1","year":"1434","subject":"بيع -مطالبة بإثبات بيع عقار تويف مالكه قبل إثبات بيعه وإفراغه -اثبات البيع وقبض الثمن باإلقرار وشهادة الشهود -احلكم بإثبات البيع -وجوب تدقيق احلكم لورود احلكم على قاصر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/5/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34203760 :‬‬\n                         ‫َر ْق ُم الدعوى‪34171007 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34295168‬تاريخه‪1434/8/13 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬مطالبــة بإثبــات بيــع عقــار تــويف مالكــه قبــل إثبــات بيعــه وإفراغــه‬\n      ‫‪ -‬اثبــات البيــع وقبــض الثمــن باإلقــرار وشــهادة الشــهود ‪ -‬احلكم بإثبات‬\n                      ‫البيــع ‪ -‬وجــوب تدقيــق احلكــم لــورود احلكــم علــى قاصــر ‪.‬‬\n\n\n\n\n                                                              ‫قاعدة ‪ :‬اإلقرار حجة ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن موكلــه اشــترى مــن مــورث املدعــى عليهــم‬\n      ‫نصيبــه املشــاع مــن األرض املوصوفــة بالصــك املذكــور يف دعــواه وســلم‬\n      ‫ثمنهــا ملورثهــم يف حياتــه فأصبــح ذلــك النصيــب املشــاع ملــك ًا ملوكلــه‪،‬‬\n      ‫ولــذا طلــب إثبــات صحــة البيــع وإفــراغ نصيــب مورثهــم ملوكلــه ‪ -‬أقــر‬\n      ‫املدعــى عليهمــا أصالــة ووكالــة وواليــة مبــا جــاء يف الدعــوى جملــة‬\n      ‫ا ‪ -‬طلبــت احملكمــة مــن املدعــي البينــة علــى دعــواه احتياط ـ ًا‬\n                                                                          ‫وتفصي ـ ً‬\n      ‫حلــق القصــار مــن الورثــة فأحضــر شــاهدين شــهدا مبــا يثبــت دعــواه‬\n      ‫وجــرى تعديلهمــا التعديــل الشــرعي‪ -‬قضــت احملكمــة بثبــوت بيــع‬\n      ‫مــورث املدعــى عليهــم نصيبــه مــن األرض محــل الدعــوى علــى املدعــي‬\n      ‫وحكمــت بإفــراغ نصيبــه املشــاع للمدعــي أصالــة ‪ -‬قنــع طرفــا الدعــوى‬\n      ‫باحلكــم إال أن احملكمــة قــررت رفعــه إلــى محكمــة االســتئناف‬\n‫‪193‬‬\n\f‫لتدقيقــه لوجــود قصــار ضمــن احملكــوم عليهــم ‪ -‬قــررت محكمــة‬\n                              ‫االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 34171007‬وتاريــخ ‪1434/04/14‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34911039‬وتاريــخ ‪1434/04/14‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1434/05/01‬ه ـ افتتحــت اجللســة الســاعة ‪11 :30‬‬\n‫وفيهــا حضــر املدعــي أصالــة (‪ )........‬ســعودي بســجل مدنــي رقــم (‪)........‬‬\n‫حضــر املدعــي وكالــة الوكيــل الشــرعي عــن (‪ )........‬ســعودي اجلنســية‬\n‫مبوجــب ســجل مدنــي رقــم (‪ )........‬مبوجــب الوكالة رقــم (‪)34506769‬‬\n‫وتاريــخ ‪1434/4/23‬هـ ـ الصــادرة مــن كتابــة عــدل محافظــة عنيــزة‬\n‫واملخــول لــه فيهــا املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإنهــاء كافــة‬\n‫اإلجــراءات املتعلقــة بذلــك وحضــر حلضــوره املدعــى عليــه أصالــة عــن‬\n‫نفســه الوكيــل الشــرعي عــن مبوجــب الوكالــة رقــم (‪ )........‬وتاريــخ‬\n‫‪1433/4/26‬هـ ـ الصــادرة مــن كتابــة عــدل عنيــزة وعــن (‪ )........‬وعــن‬\n‫(‪ )........‬وعــن (‪ )........‬بنــت (‪ )........‬مبوجــب الوكالــة رقــم (‪ )........‬وتاريــخ‬\n‫‪1433/3/12‬هـ ـ الصــادرة مــن كتابــة عــدل عنيــزة واملخــول لــه فيهــا‬\n‫املطالبــة واملرافعــة واملدافعــة واإلقــرار واإلفــراغ واســتالم القيمــة وإنهــاء‬\n                                         ‫كافــة اإلجــراءات املتعلقــة بذلــك ‪.‬‬\n‫كمــا حضــر املدعــى عليــه أصالــة ووكالــة وواليــة ولي ـ ًا عــن‬\n‫القصــر (‪ )........‬أوالد وهــم مبوجــب صــك الواليــة رقــم (‪)3395518‬‬\n                                                                                           ‫‪194‬‬\n\f      ‫وتاريخ‪1433/2/22‬ه ـ الصادر من احملكمة العامة بعنيزة ووكيال عن‬\n      ‫مبوجــب الوكالــة رقــم (‪ )34343731‬وتاريــخ ‪1434/3/21‬هـ ـ الصــادرة‬\n      ‫مــن كتابــة عــدل عنيــزة وعــن مبوجــب الوكالــة رقــم ‪33288531‬‬\n      ‫يف ‪1433/6/9‬ه ـ الصــادرة مــن كتابــة عــدل محافظــة عنيــزة وخلــف‬\n      ‫وكيــا عــن مبوجــب الوكالــة رقــم (‪ )24097‬وتاريــخ ‪1433/5/2‬هـ ـ‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل عنيــزة رقــم (‪)33288531‬‬\n      ‫وتاريــخ ‪1433/6/9‬هـ ـ وعــن (‪ )........‬وعــن (‪ )........‬وعــن(‪ )........‬وعــن‬\n      ‫(‪ )........‬وعــن (‪ )........‬وعــن (‪ )........‬مبوجــب الوكالــة رقم (‪)33100995‬‬\n      ‫وتاريــخ ‪1433/2/24‬هـ ـ الصــادرة مــن كتابــة عــدل عنيــزة وعــن مبوجب‬\n      ‫الوكالــة رقــم (‪ )33104067‬وتاريــخ ‪1433/2/27 :‬هـ ـ الصــادرة مــن‬\n      ‫كتابــة عــدل عنيــزة وعــن (‪ )........‬مبوجــب الوكالــة رقــم (‪)33332606‬‬\n      ‫وتاريــخ ‪1433/7/8 :‬هـ ـ الصــادرة مــن كتابــة عــدل عنيــزة وعــن مبوجب‬\n      ‫الوكالــة رقــم (‪ )33260086‬وتاريــخ ‪1433/5/22 :‬هـ ـ الصــادرة مــن‬\n      ‫كتابــة عــدل عنيــزة وعــن مبوجــب الوكالــة رقــم ( ‪ ) 579‬وتاريــخ ‪:‬‬\n      ‫‪1433/6/6‬هـ ـ الصــادرة مــن كتابــة عــدل محافظــة املذنــب وعــن‬\n      ‫مبوجــب الوكالــة رقــم ‪ 31349‬وتاريــخ ‪1433/6/8‬هـ ـ الصــادرة مــن‬\n      ‫كتابــة عــدل عنيــزة وعــن (‪ )........‬مبوجــب الوكالــة رقــم (‪)33291046‬‬\n      ‫وتاريــخ ‪1433/6/10‬هـ ـ الصــادرة مــن كتابــة عــدل عنيــزة وعــن (‪)........‬‬\n      ‫مبوجــب الوكالــة رقــم (‪ )33166799‬وتاريــخ ‪1433/4/3‬هـ ـ والصــادرة‬\n      ‫مــن كتابــة عــدل محافظــة عنيــزة وعــن(‪ )........‬مبوجــب الوكالــة‬\n      ‫رقــم (‪ )33284114‬وتاريــخ ‪1433/6/7‬هـ ـ واملخــول لــه فيهــا املطالبــة‬\n      ‫واملرافعــة واملدافعــة واملخاصمــة واإلفــراغ واســتالم الثمــن وإنهــاء‬\n      ‫كافــة اإلجــراءات املتعلقــة بذلــك املنحصــر إرثهــم مبوجــب الصــك رقــم‬\n\n\n‫‪195‬‬\n\f‫(‪ )3389355‬وتاريــخ ‪1433/2/17‬هـ ـ الصــادر مــن احملكمــة العامــة‬\n‫بعنيــزة ‪ ،‬وبســؤال املدعــى وكالــة عــن دعــواه أجــاب بقولــه أدعــي علــى‬\n‫املدعــى عليهــم يف هــذا املجلــس وهــم ورثــة (‪ )........‬حيــث أن موكلــي‬\n‫اشــترى نصيــب مورثهــم والــذي قــدره خمســن وربــع اخلمــس مــن الصــك‬\n‫املشــاع رقــم (‪ )1/978‬وتاريــخ ‪1410/7/2 :‬هـ ـ مببلــغ وقــدره خمســة‬\n‫ماليــن ريــال ســلمت ملورثهــم يرحمــه اهلل يف حياتــه وأصبــح نصيبــه‬\n‫مــن الصــك املشــاع ملــك ًا ملوكلــي لــذا أطلــب مــن فضيلتكــم إثبــات‬\n‫صحــة البيــع وإفــراغ نصيــب مورثهــم ملوكلــي ‪ ،‬وحــدود وأطــوال العقــار‬\n‫كمــا يلــي ‪ :‬شــما ًال ‪ :‬الشــعيب وملــك بطــول يبــدأ مــن الشــمال الغربــي‬\n‫إلــى اجلنــوب الشــرقي بطــول ‪445‬م ثــم شــرق ًا ‪ :‬بطــول ‪178‬م ثــم شــما ًال ‪:‬‬\n‫بطــول ثــم شــمال شــرق‪470‬م ثــم شــرق بطــول ‪513‬م ثــم شــرق بطــول ‪88‬م‬\n‫ثــم قليــل لشــمال الشــرقي ‪165‬م ثــم شــرق ‪115‬م ثــم شــرق بطــول ‪459‬م‬\n‫ومجموعهــا ‪2398‬م جنوب ـ ًا شــارع عــرض ‪20‬م و(‪ )........‬بطــول يبــدأ مــن‬\n‫الغــرب إلــى اجلنــوب الشــرقي ثــم شــما ًال بطــول ‪95‬م ثــم قليــل للشــمال‬\n‫الشــرقي بطــول ‪215‬م ثــم شــمال شــرق بطــول ‪1348‬م ومجموعهــا‬\n‫‪2374‬م شــرق ًا (‪ )........‬وأرض (‪ )........‬بطــول يبــدأ مــن الشــمال إلــى‬\n‫اجلنــوب بطــول ‪210‬م ثــم شــرق بطــول ‪100‬م ثــم جنــوب بطــول ‪510‬م ثــم‬\n‫قليــل للجنــوب الغربــي بطــول ‪240‬م ثــم جنــوب بطــول ‪622‬م ومجموعــة‬\n‫‪1682‬م غرب ـ ًا تبــدأ مــن اجلنــوب الشــمالي بطــول ‪305‬م ثــم شــمال غــرب‬\n‫بطــول ‪218‬م ثــم خــط متعــرج نحــو الشــمال الغربــي بطــول ‪420‬م ثــم‬\n‫شــارع عــرض عشــرين يتجــه شــرق ًا بطــول ‪1045‬م ثــم شــمال بطــول ‪38‬م‬\n‫ثــم يبــدأ حتديــد مزرعــة املســند شــمال ‪988‬م ثــم شــرق ًا ‪574‬م ثــم جنــوب‬\n‫‪1005‬م ثــم جنــوب غــرب إلــى نفــس النقطــة األولــى بطــول ‪578‬م وتتجــه‬\n\n\n                                                                                   ‫‪196‬‬\n\f      ‫إلــى مــا بعــد الشــارع إلــى الشــمال بطــول ‪214‬م ثــم شــما ًال بطــول ‪310‬م‬\n      ‫ثــم شــمال شــرق بطــول ‪560‬م ثــم شــمال بطــول ‪402‬م ومجموعــة ‪2449‬م‪.‬‬\n      ‫واملســاحة اإلجماليــة قدرهــا ثالثــة ماليــن وأربعمائــة وخمســة وعشــرين‬\n      ‫ألــف وخمســمائة متــر أطلــب إثبــات البيــع وإفــراغ نصيــب مورثهــم‬\n      ‫ملوكلــي هــذه دعــواي وبعــرض دعــوى املدعــي وكالــة علــى املدعــى‬\n      ‫عليهمــا أصالــة ووكالــة وواليــة أجابــوا بقولهــم مــا ذكــره املدعــي‬\n      ‫وكالــة مــن أن موكلنــا ميلــك خمســن وربــع اخلمــس مــن األرض الواقعــة‬\n      ‫شــمال عنيــزة مبوجــب الصــك رقــم (‪ )........‬يف ‪1410/7/24‬ه ـ وقــد‬\n      ‫بــاع موكلنــا نصيبــه حــال حياتــه للمدعــي أصالــة مببلــغ وقــدره خمســة‬\n      ‫ماليــن ريــال واســتلم املبلــغ حــال حياتــه وال مانــع لدينــا مــن إفــراغ مــا‬\n      ‫ورثنــاه مــن مورثنــا مــن العقــار املذكــور يف الدعــوى وهــو نصيــب مورثنــا‬\n      ‫البينــة‬\n           ‫وقــدره خمســن وربــع اخلمــس هكــذا أجــاب وبســؤالهم عــن ّ‬\n      ‫أجــاب املدعــي وكالــة أننــي ســلمت مورثهــم الشــيك رقــم ‪ 000437‬يف‬\n      ‫‪2010/3/21‬م املســحوب علــى بنــك (‪ )........‬والشــيك رقــم ‪001854‬‬\n      ‫يف ‪2013/2/14‬م ورقــم ‪ 001853‬يف ‪1434/3/5‬ه املســحوب علــى‬\n      ‫بنــك(‪ )........‬وأحضــر للشــهادة كل مــن (‪ )........‬ســعودي بســجل مدنــي‬\n      ‫رقــم (‪ )........‬و(‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ )........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهد كل واحــد مبفــرده أن‬\n      ‫مــورث املدعــى عليهــم قــد بــاع نصيبــه الــذي قــدره خمســن وربــع اخلمــس‬\n      ‫مــن العقــار اململــوك لــه مشــاع ًا مبوجــب الصــك رقــم(‪ )........‬يف الصــادر‬\n      ‫مــن احملكمــة العامــة بعنيــزة مببلــغ وقــدره خمســة ماليــن ريــال واســتلم‬\n      ‫املبلــغ حــال حياتــه ولــم يقــم باإلفــراغ هكــذا شــهدا وعــدال مــن قبــل‬\n      ‫(‪ )........‬ســعودي بســجل مدنــي رقــم (‪ )........‬و(‪ )........‬ســعودي بســجل‬\n\n\n‫‪197‬‬\n\f‫مدنــي رقــم (‪ )........‬حيــث شــهدا بعدالــة الشــاهدين وأنهمــا مــن أهــل‬\n‫الصــدق واألمانــة ومقبولــي الشــهادة لهمــا وعليهمــا هكــذا شــهدا وقــد‬\n‫جــرى منــي الكتابــة إلــى قســم الســجالت لدينــا مبوجــب خطابنــا رقــم‬\n‫‪ 341017519‬يف ‪1434/4/24‬ه ـ لالستفســار عــن الصــك رقــم ‪1/978‬‬\n‫يف ‪1410/7/24‬ه ـ وهــل هــو ســاري املفعــول وصالــح لالعتمــاد عليــه‬\n‫عنــد اإلفــراغ فبنــاء علــى مــا تقــدم وحيــث طلــب املدعــي وكالــة إثبــات‬\n‫البيــع اإلفــراغ وحيــث أقــر املدعــى عليهــم أصالــة ووكالــة بصحــة البيــع‬\n‫وحيــث أحضــر املدعــي وكالــة بينــه شــهدت بــأن مــورث املدعــى عليهــم‬\n‫قــد بــاع نصيبــه مــن األرض حــال حياتــه وحيــث جــرى منــي االستفســار‬\n‫عــن ســريان مفعــول الصــك وأنــه صالــح لالعتمــاد عليــه وحيــث أبــرز‬\n‫املدعــي وكالــة صــورة مــن الشــيك املســلم ملــورث املدعــى عليهــم أصالــة‬\n‫ووكالــة وواليــة لــذا فقــد ثبــت لــدي بيــع مــورث املدعــى عليهــم أصالــة‬\n‫ووكالــة وواليــة (‪ )........‬نصيبــه مــن األرض اململوكــة مبوجــب الصــك‬\n‫رقــم ‪ 1/978‬يف ‪1410/7/24‬ه ـ الصــادر مــن احملكمــة العامــة بعنيــزة‬\n‫وحكمــت بإفــراغ نصيبــه والــذي قــدره خمســن وربــع اخلمــس للمدعــى‬\n‫أصالــة (‪ )........‬هــذا مــا ظهــر لــي وبعرضــه عليهــم قــرروا قناعتهــم‬\n‫بذلــك وأفهمتهــم بأننــي ســوف أرفــع هــذا اإلجــراء حملكمــة االســتئناف‬\n‫بالقصيــم لتدقيــق احلكــم لوجــود القصــر وســوف يتــم التهميــش علــى‬\n‫صــك امللكيــة بإفــراغ نصيــب للمدعــي بعــد تصديــق احلكــم مــن‬\n‫محكمــة االســتئناف ثــم بعثــه لســجله للتهميــش عليــه بذلــك ففهمــوا‬\n‫ذلــك وعليــه جــرى التوقيــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/1‬ه ـ‬\n‫ويف يــوم االثنــن املوافق‪1434/07/24‬ه ـ افتتحــت اجللســة الســاعة‬\n\n\n                                                                                  ‫‪198‬‬\n\f      ‫العاشــرة والربــع صباحــا وفيهــا عــادت إلينــا املعاملــة مــن محكمــة‬\n      ‫االستئناف بالقصيم وبرفقها القرار رقم ‪ 34252823‬يف ‪1434/6/27‬هـ‬\n      ‫واملتضمــن املالحظــة مبــا يلــي أو ًال ‪ :‬لــم يتحقــق فضيلتــه مــن البنــك عمــن‬\n      ‫اســتلم الشــيكني املذكوريــن ‪ .‬ثاني ـ ًا ‪ :‬لــم يرفــق فضيلتــه أصــل صــك‬\n      ‫امللكيــة أو صــورة مصدقــة منــه مــع مــا عليــه مــن تظهيــرات ‪ .‬ثالث ـ ًا ‪:‬‬\n      ‫صــور الصكــوك والــوكاالت املرفقــة لــم تصــدق مبطابقتهــا ألصلهــا ‪.‬‬\n      ‫رابعـ ًا ‪ :‬لــم يرصــد مضمــون إجابتــه الســجالت بخصــوص صــك التملــك ‪.‬‬\n      ‫خامسـ ًا ‪ :‬يوجــد يف الضبــط والصــك يف الصفحــة الثانيــة منــه كالم ال‬\n      ‫عالقــة لــه بالقضيــة مشــار إلــى موضعــه بالقلــم ‪ .‬سادسـ ًا ‪ :‬أثبــت فضيلتــه‬\n      ‫بيــع مــورث املدعــى عليهــم نصيبــه مــن األرض املذكــورة وحكــم بإفــراغ‬\n      ‫نصيبــه للمدعــى أصالــة ‪ ..‬والصحيــح أن يكتفــي بإثبــات البيــع ويقــرر‬\n      ‫التهميــش علــى صــك التملــك مبــا ثبــت لديــه بعــد تصديــق احلكــم وال‬\n      ‫حاجــة للحكــم باإلفــراغ وعليــه أجيــب عــن املالحظــة األولــى أن املدعــى‬\n      ‫عليهــم أقــروا بصحــة البيــع وبــأن مورثهــم قــد أســتلم جميــع املبلــغ حــال‬\n      ‫حياتــه وشــهد الشــهود املعدلــن بذلــك واإلقــرار أقــوى األدلــة وقــد أجمــع‬\n      ‫الفقهــاء علــى ذلــك النتفــاء التهمــه فيــه غالبـ ًا ونــص فقهــاء احلنابلــة علــى‬\n      ‫أن املدعــى عليــه أذا أعتــرف باحلــق ال تســمع عليــه الشــهادة وإمنــا تســمع‬\n      ‫إذا أنكــر اإلقــرار هــو أخبــار الشــخص بثبــوت حــق للغيــر علــى نفســه‬\n      ‫وقــد أحضــر املدعــي كشــف حســاب باســمه مــن مصــرف(‪)........‬‬\n      ‫موضح ـ ًا فيــه أنــه مت صــرف شــيك مببلــغ مليــون ريــال باســم (‪ )........‬يف‬\n      ‫‪ 1430/6/28‬ه ـ رقــم الشــيك ‪ 69‬وأجيــب علــى املالحظــة الثانيــة أنــه‬\n      ‫مت أرفــاق صــورة مصدقــه مــن الصــك وأجيــب عــن املالحظــة الثالثــة‬\n      ‫أنــه مت املصادقــة علــى صــور الصكــوك والــوكاالت وأجيــب عــن‬\n\n\n‫‪199‬‬\n\f‫املالحظــة الرابعــة أنــه مت بعــث خطــاب لســعادة رئيــس الســجالت برقــم‬\n‫‪ 341017519‬يف ‪1434/4/24‬ه ـ لالستفســار عــن الصــك رقــم ‪1/978‬‬\n‫يف ‪1410/7/24‬ه ـ فوردنــا جوابهــم بنفــس الرقــم واملتضمــن أن الصــك‬\n‫ســاري املفعــول وال يوجــد عليــه مالحظــات وأجيــب عــن املالحظــة‬\n‫اخلامســة أنــه مت شــطب مــاال عالقــة لــه بالقضيــة وأجيــب عــن املالحظــة‬\n‫السادســة أننــي رجعــت عــن قــول حكمــت باإلفــراغ وقــررت التهميــش‬\n‫علــى الصــك بعــد تصديــق احلكــم مــن محكمــة االســتئناف وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪1434/7/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنا نحن قضــاة الدائرة احلقوقية الثانية‬\n‫مبحكمــة االســتئناف مبنطقــة القصيــم على املعاملة الــواردة من فضيلة‬\n‫رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم ‪ 341448017‬وتاريــخ‬\n‫‪1434/7/16‬ه اخلاصــة بدعــوى (‪ )........‬ضــد (‪ )........‬أصالــة ووكالــة‬\n‫عــن بقيــة ورثــة والدهمــا بشــأن ادعائــه شــراء نصيــب مــورث املدعــى‬\n‫عليهــم مــن العقــار املذكــور يف الدعــوى الواقــع شــمال عنيــزة وقــدره‬\n‫خمســان وربــع اخلمــس ؛ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ (‪ )........‬برقــم ‪ 34203760‬وتاريــخ ‪1434/5/1‬هــ؛‬\n‫املتضمــن أنــه ثبــت لــدى فضيلتــه بيــع مــورث املدعــى عليهــم أصالــة‬\n‫ووكالــة وواليــة (‪ )........‬نصيبــه مــن األرض املذكــورة وحكــم بإفــراغ‬\n‫نصيبــه للمدعــى (‪ ،)........‬كمــا هــو مــدون ومفصــل فيــه؛ املالحــظ عليه‬\n‫ســابقاً‪ .‬وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصــك‬\n‫ـاء علــى قرارانــا رقــم ‪ 34252823‬وتاريــخ ‪1434/6/27‬ه ـ ؛ قررنــا ‪:‬‬       ‫بنـ ً‬\n‫التصديــق علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬مــع تنبيــه فضيلتــه إلــى‬\n\n\n                                                                                   ‫‪200‬‬\n\f      ‫أن مــا ذكــره فضيلتــه يف جوابــه عــن الفقــرة األولــى مــن القــرار مــن أن‬\n      ‫اإلقــرار أقــوى األدلة‪...‬إلــخ؛ معلــوم يف حــق جائــز التصــرف أمــا القاصــر‬\n      ‫ونحــوه فــا يلزمــه إقــرار غيــره‪ ،‬فيالحــظ ذلــك ‪ .‬واهلل املوفــق؛ وصلــى‬\n                                     ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":193,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ce4738a141949f90c8a469a24cd1a588bb3c8766bd45d7d4b3193db6f81e12c3","normalized_text_hash":"eaaad042d335a2090582d4fd99a38eba11469b9f6e763f6dcfcb5783a3c0280e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p193-34203760"},{"id":"05099e43-1fbc-545f-aeee-b82ac11750db","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -وعد بالشراء بعد التملك -اإلتفاق على شراء فيا ثم بيعها ثانية على دفعات -سداد جزء من املبلغ مبوجب عقد - إخال البائع بإلتزاماته التعاقدية -املطالبة برد املبلغ -وجود سند -حلف اليمن -عدم حضور املدعى عليه -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم -احلكم غيابي ا برد املبلغ -الغائب على حجته متى حضر .","document_number":"34334270","case_number":"34173586","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/19","year":"1434","subject":"بيع -وعد بالشراء بعد التملك -اإلتفاق على شراء فيا ثم بيعها ثانية على دفعات -سداد جزء من املبلغ مبوجب عقد - إخال البائع بإلتزاماته التعاقدية -املطالبة برد املبلغ -وجود سند -حلف اليمن -عدم حضور املدعى عليه -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم -احلكم غيابي ا برد املبلغ -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/10/19 :‬هـ‬\n                 ‫ُ‬                  ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪34334270 :‬‬\n                     ‫َر ْق ُم الدعوى‪34173586 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35119817‬تاريخه‪1435/1/18 :‬هـ‬\n\n\n  ‫بيــع ‪ -‬وعــد بالشــراء بعــد التملــك ‪ -‬اإلتفــاق علــى شــراء فيــا ثــم‬\n  ‫بيعهــا ثانيــة علــى دفعــات‪ -‬ســداد جــزء مــن املبلــغ مبوجــب عقــد ‪-‬‬\n  ‫إخــال البائــع بإلتزاماتــه التعاقديــة ‪ -‬املطالبــة بــرد املبلــغ‪ -‬وجــود ســند‬\n  ‫‪ -‬حلــف اليمــن ‪ -‬عــدم حضــور املدعــى عليــه ‪ -‬رفــع احلكــم حملكمــة‬\n  ‫االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪ -‬احلكــم غيابي ـ ًا بــرد‬\n                                   ‫املبلــغ ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n                     ‫‪ -1‬قوله تعالى (يا أيها الذين آمنوا أوفوا بالعقود) ‪.‬‬\n        ‫‪ -2‬وحلديث (املسلمون على شروطهم) رواه الترمذي وأبو داوود ‪.‬‬\n              ‫‪ -3‬وحلديث (على اليد ما أخذت حتى تؤديه) رواه األربعة‪.‬‬\n  ‫‪ -4‬وحلديــث (البينــة علــى املدعــي واليمــن علــى املدعــى عليــه) رواه‬\n  ‫الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب‬\n  ‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n                                                          ‫علــى املدعــى عليــه‪.‬‬\n                        ‫‪ -5‬املادة ‪ 55‬و ‪ 5/176‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n  ‫ادعــى املدعــي بــأن موكلتــه قامــت باإلتفــاق مــع املدعــى عليهــا ‪،‬‬\n  ‫مؤسســة ‪ .......‬للمقــاوالت العامــة ‪ ،‬علــى أن تقــوم املدعــى عليهــا بشــراء‬\n\n                                                                                       ‫‪202‬‬\n\f      ‫فيــا مببلــغ معــن ثــم تقــوم ببيــع هــذه الفيــا ملوكلتــه مببلــغ أعلــى‬\n      ‫تســدد علــى أقســاط‪ ،‬وبالترتيــب علــى ذلــك قامــت موكلتــه بدفــع مبلــغ‬\n      ‫معــن لهــذه املؤسســة مبوجــب ســند قبــض علــى أوراق هــذه املؤسســة ‪،‬‬\n      ‫وقــد مت االتفــاق علــى أن يتــم إفــراغ القطعــة محــل الدعــوى للمؤسســة‬\n      ‫املدعــى عليهــا يف موعــد محــدد إال أن ذلــك لــم يحــدث‪ ،‬لــذا طلــب إلــزام‬\n      ‫املدعــى عليهــا بإعــادة املبلــغ املدفــوع ‪ ،‬وتأكيــد ًا لذلــك قــدم املدعــي‬\n      ‫وكالــة للمحكمــة صــورة عقــد البيــع وأصــل ســند القبــض وصــورة‬\n      ‫صــك العقــار‪ ،‬ويف إحــدى اجللســات حضــرت املدعيــة بنــاء ًا علــى طلــب‬\n      ‫احملكمــة وحلفــت اليمــن بصحــة مــا تقــدم‪ ،‬وترتيب ـ ًا علــى مــا تقــدم‬\n      ‫باإلضافــة إلــى عــدم العثــور علــى صاحــب املؤسســة املدعــى عليهــا رغــم‬\n      ‫إيقــاف خدماتــه‪ ،‬وحيــث أن األصــل بقــاء مــا كان علــى مــا كان فقــد‬\n      ‫حكمــت احملكمــة علــى املدعــى عليهــا الغائبــة عــن مجلــس القضــاء‬\n      ‫بدفــع املبلــغ الــذي قامــت املدعيــة بدفعــه بــداءة‪ ،‬وأفهمــت احملكمــة‬\n      ‫املدعيــة بــأن الغائــب علــى حجتــه متــى حضــر ‪ ،‬وقــررت بعــث املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقــق احلكــم كــون احلكــم صــدر علــى غائــب‬\n      ‫تعــذر العثــور عليــه‪ ،‬وقــد قنعــت املدعيــة مبــا تقــدم ‪ ،‬صــدق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 34173586‬وتاريــخ‬\n      ‫‪1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34925425‬وتاريــخ‬\n\n‫‪203‬‬\n\f‫‪1434/04/15‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/07/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر ‪ ..............‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .........‬بصفتــه وكيــا عــن املدعيــة ‪.........‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬وبالوكالــة رقــم‬\n‫‪ 9662‬وتاريــخ ‪1431/2/2‬ه ـ جلــد ‪ ، 9243‬ولــم يحضــر املدعــى عليــه‬\n‫‪ .......‬وال مــن ميثلــه ‪ ،‬وقــد وردنــا خطــاب مديــر شــرطة محافظــة جــدة رقم‬\n‫‪ 25/1/20/4857‬وتاريــخ ‪1434/6/11‬ه ـ مفاده(أنــه مت االتصــال علــى‬\n‫جــوال املذكــور رقــم (‪ )..............‬اكثــر مــن مــره ويف أوقــات متفاوتــة‬\n‫ولــم يتــم الــرد ‪ ،‬وبالبحــث والتحــري عنــه لــم يتــم العثــور عليــه ومــازال‬\n                                                                  ‫البحــث جاري)أ‪.‬ه ـ‬\n‫وقــرر املدعــي وكالــة قائــا ‪ :‬أطلــب التعميــم وإيقــاف خدمــات املدعــى‬\n‫عليه ‪ .‬ثم رفعت اجللسة لذلك ‪ .‬ويف يوم االثنني املوافق ‪1434/10/19‬هـ‬\n‫افتتحت اجللســة الســاعة ‪ 10 : 00‬وفيها حضر املدعي وكالة ‪،............‬‬\n‫ولــم يحضــر املدعــى عليــه ‪ .............‬وال مــن ميثلــه ‪ ،‬ولــم يردنــا مــا يفيــد‬\n‫تبليغــه ‪ ،‬وقــد جــرت الكتابــة إلــى محافظــة جــدة إليقــاف خدمــات‬\n‫املدعــى عليــه برقــم ‪ 341785828‬وتاريــخ ‪1434/7/29‬ه ـ ولــم يرجعنــا‬\n‫حتــى اليــوم ‪ ،‬لــذا فقــد قــررت النظــر يف الدعــوى غيابيــا يف حــق املدعــى‬\n‫عليــه ‪ ،‬ثــم قــرر املدعــي وكالــة قائــا ‪ :‬أطلــب تصحيــح دعــواي لتكــون‬\n‫يف مواجهــة مؤسســة ‪ .............‬للمقــاوالت العامــة بالســجل التجــاري رقــم‬\n‫‪...............‬لصاحبهــا ‪ ...........‬بالســجل املدنــي رقــم ‪ . ...............‬ثــم ادعــى‬\n‫املدعــي وكالــة قائــا ‪ :‬لقــد قامــت موكلتــي باالتفــاق مــع املدعــى‬\n‫عليهــا مؤسســة ‪ ..............‬للمقــاوالت العامــة وميثلهــا صاحبهــا ‪...............‬‬\n‫علــى أن تقــوم املدعــى عليهــا بشــراء فيــا مســاحتها (‪320.50‬م‪ )2‬يف‬\n\n\n                                                                                             ‫‪204‬‬\n\f      ‫املخطــط رقــم ‪/243‬ب‪ ،‬علــى القطعــة رقــم ‪/720‬أ يف مدينــة جــدة بحــي‬\n      ‫الياقــوت ‪ ،‬مببلــغ قــدره مليــون ومائــة ألــف ريــال مــن شــركة ‪ ........‬والتــي‬\n      ‫متلــك القطعــة محــل الدعــوى مبوجــب الصــك الصــادر مــن كتابــة العــدل‬\n      ‫األولــى بجــدة برقــم ‪ 420208009290‬وتاريــخ ‪1434/2/10‬هــ‪ ،‬ثم تقوم‬\n      ‫املدعــى عليهــا ببيــع هــذه الفيــا ملوكلتــي مببلــغ قــدره مليــون وثمامنائــة‬\n              ‫واثنــان وأربعــون ألفــا وخمســمائة ريــال تدفــع علــى النحــو التالــي ‪:‬‬\n      ‫‪ -1‬دفعــة مقدمــة عنــد توقيــع العقــد قدرهــا مائــة وعشــرة آالف ريــال دفــع‬\n      ‫منهــا مبلغــا قــدره خمســون ألــف ريــال واملتبقــي منهــا قــدره ســتون ألــف‬\n      ‫ريــال تدفــع يف موعــد أقصــاه أســبوعني مــن تاريــخ حتريــر العقــد املبــرم‬\n                                                                          ‫بــن الطرفــن ‪.‬‬\n      ‫‪ -2‬املبلــغ املتبقــي وقــدره تســعمائة وتســعون ألــف ريــال تدفــع علــى‬\n      ‫أقســاط شــهرية ملــدة ثالثمائــة شــهر ‪ ،‬قــدر القســط الواحــد مبلغــا قــدره‬\n                                ‫خمســة آالف وســبعمائة وخمســة وســبعون ريــاال ‪.‬‬\n      ‫مبوجــب عقــد بيــع فيــا بالتقســيط املــؤرخ يف ‪1434/3/11‬ه ـ احملــرر‬\n      ‫علــى أوراق مؤسســة ‪ .............‬للمقــاوالت العامــة ‪ ،‬وقــد ســلمت‬\n      ‫موكلتــي املبلــغ املــدون يف العقــد وقــدره خمســون ألــف ريــال مبوجــب‬\n      ‫ســند قبــض رقــم ‪ 0257‬وتاريــخ ‪1434/3/9‬ه ـ علــى أوراق مؤسســة‬\n      ‫‪ ...........‬للمقــاوالت العامــة ‪ ،‬وقــد مت االتفــاق علــى يتــم إفــراغ القطعــة‬\n      ‫محــل الدعــوى للمؤسســة املدعــى عليهــا يف موعــد محــدد ليطمئــن قلــب‬\n      ‫موكلتــي مــن صحــة انتقــال العقــار للمدعــى عليهــا ‪ ،‬ولــم يحضــر مــن‬\n      ‫ميثــل املدعــى عليهــا لإلفــراغ ‪ ،‬ومبراجعــة املدعــى عليهــا وجــد املكتــب‬\n      ‫مغلقــا ‪ ،‬ووجــد هنــاك جمــع مــن النــاس حالهــم مثــل حــال موكلتــي ‪،‬‬\n      ‫وتقدمنــا جميعــا بشــكوى ضــد املدعــى عليهــا لــدى الشــرطة فأفهمنــا‬\n\n\n‫‪205‬‬\n\f‫بتقــدمي الدعــوى لــدى احملكمــة ‪ ،‬أطلــب إلــزام املدعــى عليهــا بإعــادة‬\n‫املبلــغ املدفــوع لهــا وقــدره خمســون ألــف ريــال ‪ .‬هــذه عــواي ‪ .‬وبســؤال‬\n‫املدعــي وكالــة عــن بينتــه علــى صحــة الدعــوى قــال ‪ :‬بينتــي هــي عقــد‬\n‫البيــع وســند القبــض وصــورة صــك العقــار محــل الدعــوى واملشــار إليهــا‬\n‫يف الدعــوى ‪ .‬ثــم أبــرز املدعــي وكالــة أصــل عقــد البيــع وأصــل ســند‬\n‫القبــض وصــورة صــك العقــار ‪ ،‬ومت تزويــد املعاملــة بنســخة منهــا ‪ ،‬ثــم‬\n‫طلبــت مــن املدعــي إحضــار موكلتــه فحضــرت املدعيــة أصالــة ‪.............‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ، ............‬وبعــرض‬\n‫اليمــن عليهــا علــى صحــة الدعــوى وعــدم اســترجاعها مــن مبلــغ الدعــوى‬\n‫شــيئا اســتعدت لذلــك ‪،‬ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أننــي اتفقــت مــع املدعــى عليهــا مؤسســة ‪ .........‬للمقــاوالت العامــة‬\n‫وميثلهــا صاحبهــا ‪............‬علــى أن تقــوم املدعــى عليهــا بشــراء فيــا‬\n‫مســاحتها(‪320.50‬م‪ )2‬يف املخطــط رقــم ‪/243‬ب ‪ ،‬علــى القطعــة رقــم‬\n‫‪/720‬أ يف مدينــة جــدة بحــي الياقــوت ‪ ،‬مببلــغ قــدره مليــون ومائــة ألــف‬\n‫ريــال مــن شــركة ‪ .............‬والتــي متلــك القطعــة محــل الدعــوى مبوجــب‬\n‫الصــك الصــادر مــن كتابــة العدل األولى بجدة برقــم ‪420208009290‬‬\n‫وتاريــخ ‪1434/2/10‬ه ـ ‪ ،‬ثــم تقــوم املدعــى عليهــا ببيــع هــذه الفيــا لــي‬\n‫مببلــغ قــدره مليــون وثمامنائــة واثنــان وأربعــون ألفــا وخمســمائة ريــال‬\n                                                      ‫تدفــع علــى النحــو التالــي ‪:‬‬\n‫‪ -1‬دفعــة مقدمــة عنــد توقيــع العقــد قدرهــا مائــة وعشــرة آالف ريــال دفــع‬\n‫منهــا مبلغــا قــدره خمســون ألــف ريــال واملتبقــي منهــا قــدره ســتون ألــف‬\n‫ريــال تدفــع يف موعــد أقصــاه أســبوعني مــن تاريــخ حتريــر العقــد املبــرم‬\n                                                                     ‫بــن الطرفــن ‪.‬‬\n\n\n                                                                                        ‫‪206‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":202,"source_page_end":206,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aaecc582c9020edc8c1a7026506e0b693ebb0c1ef9c9006215650a7e1f66e586","normalized_text_hash":"ebda446ac020c834cbe76383bd18cd8123cb2e8aa5576e0760148d14f878049d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p202-34334270"},{"id":"88164077-5595-557d-bc76-68e3a219f28c","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -أرض زراعية -اإللزام باإلفراغ -طلب إفراغ العقار -بيع العقار قبل فرزه -إقرار بصحة البيع -من سعى يف نقض ما مت من جهته فسعية مردود عليه -الدعوى تقام على من بيده العن -املطالبة بأتعاب احملاماة -التهميش على صك امللكية .","document_number":"34179277","case_number":"33169815","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"بيع -عقار -أرض زراعية -اإللزام باإلفراغ -طلب إفراغ العقار -بيع العقار قبل فرزه -إقرار بصحة البيع -من سعى يف نقض ما مت من جهته فسعية مردود عليه -الدعوى تقام على من بيده العن -املطالبة بأتعاب احملاماة -التهميش على صك امللكية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34179277 :‬‬\n                   ‫َر ْق ُم الدعوى‪33169815 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34234860‬تاريخه‪1434/6/10 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــار ‪ -‬أرض زراعيــة ‪ -‬اإللــزام باإلفــراغ ‪ -‬طلــب إفــراغ العقــار‬\n‫‪ -‬بيــع العقــار قبــل فــرزه ‪ -‬إقــرار بصحــة البيــع ‪ -‬مــن ســعى يف نقــض‬\n‫مــا مت مــن جهتــه فســعية مــردود عليــه ‪ -‬الدعــوى تقــام علــى مــن بيــده‬\n‫العــن ‪ -‬املطالبــة بأتعــاب احملامــاة ‪ -‬التهميــش علــى صــك امللكيــة ‪.‬‬\n\n\n\n\n             ‫‪ -1‬قاعدة من سعى يف نقض ما مت جهته فسعيه مردود عليه‬\n                                    ‫‪ -2‬قاعدة الدعوى تقام على من بيده العني‬\n‫‪ -3‬قــال يف رد احملتــار علــى الــدر املختــار ‪ ( 328/327/7‬بــاع عبــد غيــره‬\n‫ا علــى إقــرار البائــع الفضولــي أو علــى‬       ‫بغيــر إذنــه فبرهــن املشــتري مثـ ً‬\n‫إقــرار رب العبــد أنــه لــم يأمــره بالبيــع للعبــد وأراد املشــتري رد البيــع ردت‬\n‫بينتــه ولــم يقبــل قولــه للتناقــض كمــا لــو أقــام البائــع البينــة أنــه بــاع‬\n‫بــا أمــر أو برهــن علــى إقــرار املشــتري بذلــك وأصلــه أن مــن ســعى يف‬\n                                              ‫نقــض مــا مت مــن جهتــه ال يقبــل ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة بــأن موكلــه اشــترى ثــاث قطــع زراعيــة مــن‬\n‫املدعــى عليــه ( ذكــر اســمائها وحدودهــا) والشــراء مت بعــد تقســيم‬\n\n                                                                                          ‫‪210‬‬\n\f      ‫امليــراث وحيــازة املدعــى عليــه نصيبــة وموافقــة الورثــة علــى القســم‬\n      ‫وكذلــك موافقتهــم علــى البيــع وعلمهــم بــه ‪ ،‬ثــم قــام املدعــى عليــه ببيــع‬\n      ‫احــدى القطــع علــى شــخص آخــر ‪ ،‬طلــب املدعــي وكالــة احلكــم علــى‬\n      ‫املدعــى عليــه بإلزامــه بإفــراغ جميــع املبيــع ( األراضــي الزراعيــة الثــاث‬\n      ‫املذكــورة) والتــي مت بيعهــا مبوجــب عقــود البيــع املرفقــة وقبــض املدعــى‬\n      ‫عليــه ثمنهــا والتهميــش علــى الصــك والــزام املدعــى عليــه بدفــع اتعــاب‬\n      ‫احملامــاة خمســن ألــف ريــال‪ ،‬اجــاب املدعــى عليــه وكالــة بــأن البيــع‬\n      ‫باطــل شــرع ًا ألن املدعــي أقــر يف صحيفــة دعــواه بــأن البيــع مت بتاريــخ‬\n      ‫‪1427/10/14‬ه ـ واملدعــى عليــه لــم يكــن ميلــك املبيــع كمــا أن البيــع‬\n      ‫ورد علــى قطعتــن مفرزتــن واملدعــى عليــه وقــت البيــع كان ميلكهــا‬\n      ‫علــى املشــاع بينــه وبــن اخوتــه وبقيــة الورثــة لــم يوافقــوا ومت ابــاغ املدعى‬\n      ‫بذلــك وتســليمة املبلــغ فرفــض ذلــك‪ ،‬طلــب املدعــى عليــه وكالــة رد‬\n      ‫الدعــوى والــزام املدعــي بأتعــاب احملامــاة ‪ ،‬انكــر املدعــي وكالــة مــا‬\n      ‫دفــع بــه املدعــى عليــه وكالــه وذكــر بــأن الصحيــح أن تقســيم نصيــب‬\n      ‫والــد املدعــى عليــه بــن ورثتــه قــد مت قبــل شــراء موكلــه لنصيــب املدعــى‬\n      ‫عليــه اال أن االفــراغ قــد تأخــر لغــرض اســتكمال االجــراءات النظاميــة‬\n      ‫والكروكيــات وممــا يقــوى ذلــك أن املبيــع هــو نفــس نصيبــة ‪ ،‬جــرى‬\n      ‫االطــاع علــى صــك حصــر ورثــة والــد املدعــى عليــه وصكــوك امللــك‬\n      ‫ومهمــش علــى صــك القطعــة الثالثــة بانتقالهــا لشــخص آخــر‪ ،‬ملــا قــرره‬\n      ‫الفقهــاء مــن أن مــن ســعى يف نقــض مــا مت مــن جهتــه فســعيه مــردود‬\n      ‫عليــه وألن الدعــوى تقــام علــى مــن بيــده العــن فقــد صــدر احلكــم بثبــوت‬\n      ‫ملكيــة املدعــي لقطعتــي األرض الزراعيــة ( ذكرهمــا ورقــم الصــك‬\n      ‫) وصــرف النظــر عــن طلبــه اثبــات ملكيتــه للقطعــة الثالثــة ( ذكــر‬\n\n\n‫‪211‬‬\n\f‫اســمها ) وأمــر القاضــي التهميــش علــى صــك امللكيــة مبوجبــه بعــد‬\n‫اكتســاب احلكــم القطعيــة وأفهــم املدعــي بــأن لــه اقامــة دعــواه فيمــا‬\n‫يخــص القطعــة الثالثــة علــى مــن بيــده العــن ‪ ،‬لــم يقنــع املدعــى عليــه‬\n                    ‫باحلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33169815‬وتاريــخ ‪ 1433/03/08‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33446910‬وتاريــخ ‪ 1433/03/08‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق‪ 1433/04/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬بصفته وكيــا عن ‪ ...‬مبوجب‬\n‫الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة بشــمال محافظة جــدة برقم‬\n‫‪ ....‬وتاريــخ ‪1433/4/19‬ه ـ جلــد ‪ 11641‬وهــي تخولــه املرافعــة واملدافعــة‬\n‫و‪...‬وكل بصفتــه وكيــا عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل أبهــا برقــم ‪ ....‬يف ‪1433/3/12‬ه ـ وحضــر حلضــوره ‪ ...‬يحمــل‬\n‫ســجل مدنــي رقــم ‪...‬بصفتــه وكيــا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة‬\n‫مــن كتابــة عــدل تنومــه برقــم ‪ 1‬وتاريــخ ‪1433/4/18‬ه ـ وهــي تخولــه‬\n‫الدعــوى والصلــح والتنــازل وطلــب اليمــن وبســؤال املدعــي وكالــة عــن‬\n‫دعــواه قــال أطلــب إمهالــي لتحريرهــا وعليــه رفعــت اجللســة ويف جلســة‬\n‫أخــرى حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬بصفتــه‬\n‫وكيــا عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بأبهــا رقــم ‪ 4933‬يف ‪1433/3/12‬ه ـ املخولــة لــه املرافعــة واملدافعــة‬\n\n                                                                                   ‫‪212‬‬\n\f      ‫وحضــر حلضــوره املدعــى عليــه وكالــة احلاضــر يف اجللســة الســابقة‬\n      ‫وبســؤال املدعــي عــن دعــواه أبــرز مذكــرة مكونــة مــن أربــع صفحــات‬\n      ‫ونــص احلاجــة منهــا كمــا يلــي فإنــه إشــارة إلــى الدعــوى املقيــدة لــدى‬\n      ‫مكتبكــم برقــم ‪ 33446910‬مــن موكلــي املدعــي ‪... :‬ضــد املدعــى‬\n      ‫عليــه ‪...‬واملتضمنــة املطالبــة بإفــراغ القطعتــن ‪ ...‬و‪...‬واحملــدودة كالتالــي‬\n      ‫‪:‬شــرقا‪ :‬ملــك ‪...‬بطــول ‪ 20‬متــر ًا ‪.‬وغربـاً‪ :‬ملــك ‪...‬بطــول ‪12‬متــر ًا ‪.‬وشــماالً‪:‬‬\n      ‫مجــرى ســيل بطــول ‪ 60‬متــر ًا ‪.‬وجنوب ـاً‪ :‬ملــك ‪...‬وملــك ورثــة ‪...‬وســبيل‬\n      ‫مــاء للبئــر ومجرتهــا ســبيل قــدمي يف مــا بــن ‪ ...‬و‪ ...‬بعــرض نصــف متــر‬\n      ‫وهــي أراضــي زراعيــة واملدعــي اشــترى مــن املدعــى عليــه بعــد تقســيم‬\n      ‫امليــراث بــن الورثــة واملدعــي عــم املدعــى عليــه وبعــد حيــازة املدعــى‬\n      ‫عليــه لنصيبــه وموافقــة الورثــة علــى القســم وكذلــك موافقتهــم علــى‬\n      ‫البيــع وعلمهــم بــه ومرفــق إقــرار املدعــى عليــه بذلــك وأخــوه ‪...‬شــاهد‬\n      ‫علــى االقــرار مرفــق مســتند رقــم (‪ )1‬ونصــه (أقــر أنــا املدعــو ‪...‬حامــل‬\n      ‫ســجل مدنــي رقــم ‪...‬تاريــخ ‪1404/6/22‬ه ـ مصدرهــا مكــة املكرمــة‬\n      ‫بأنــي قــد بعــت كامــل ورثــي مــن والــدي الكائــن يف محافظــة ‪ ...‬بــاد‬\n      ‫‪ ...‬يف قريــة آل ‪...‬مــن عمــي شــقيق والــدي ‪... ،‬بيــع ال رجعــة فيــه وأنــي‬\n      ‫قــد اســتلمت جميــع حقوقــي املاديــة مبلــغ وقــدره (خمســة وأربعــن ألــف‬\n      ‫ريــال) مقابــل أمالكــي التــي ورثتهــا عــن والــدي مــن جائــز أخوانــي‬\n                                  ‫املوجوديــن حســب صــك الورثــة وهــي كاآلتــي‪:‬‬\n      ‫‪ -1‬قطعــة الصفــى العثــري شــما ًال بطــول ‪ 30‬متــر يليــه حصــة ‪...‬وجنوبــا‬\n      ‫بطــول ‪ 30‬متــر يليــه ســبيل بعــرض ‪ 5‬أمتــار وغربــا بطــول ‪ 10‬أمتــار‬\n      ‫يليــه ملــك ‪ ...‬و‪...‬وشــرقا بطــول ‪ 10‬أمتــار يليــه ســبيل بعــرض ‪ 5‬أمتــار‬\n      ‫‪-2 .‬الظاهــرة الســفلي واحلفــدة احملــددة كاآلتــي‪ :‬شــرقا بطــول ‪20‬‬\n\n\n‫‪213‬‬\n\f‫متــر يليــه ملــك ‪...‬شــماال بطــول ‪ 60‬متــر يليــه مجــرى ســيل غربــا بطــول‬\n‫‪ 12‬متــر يليــه ملــك ‪ ...‬وجنوبــا بطــول ‪ 55‬متــر يليــه ملــك ‪...‬وملــك ورثــة‬\n‫‪...‬وســبيل مــاء للبئــر ومجرتهــا ســبيل قــدمي يف مــا بــن الظاهــرة الســفلي‬\n‫واحلفــدة بعــرض نصــف متــر ‪ .‬املقــر مبــا فيــه‪ .... /‬وشــهد بذلــك ‪...... ...‬‬\n‫وختــم مكتــب ‪...‬للعقــار ) كمــا واملدعــى عليــه بــاع ملكــه اخلــاص‬\n‫بــه وهــو بكامــل األهليــة املعتبــرة شــرع ًا ومرفــق عقــد البيــع وعليــه‬\n‫إقــراره وتوقيعــه والشــهود مســتند رقــم (‪ )3()2‬ونصــه عقــد بيــع بتاريــخ‬\n‫‪1427/10/14‬ه ـ الطــرف األول البائــع ‪...‬الطــرف الثانــي املشــتري ‪...‬‬\n‫علــى أوالً‪ :‬لقــد بــاع الطــرف األول للطــرف الثانــي األرض الواقعــة يف‬\n‫بــاد ‪ ...‬والواقعــة يف ســبت تنومــة قريــة‪ ....‬موقعهــا ومســاحتها اإلجماليــة‬\n‫وواجهاتهــا وحدودهــا كاآلتــي‪ :‬شــما ًال ‪ :‬بطــول ســتون متــر ًا ‪60‬م يحدهــا‬\n‫مجــرى ‪ ....‬جنوبــا‪ :‬بطــول خمســة وخمســون متــر ًا يليــه ملــك ‪...‬وملــك ورثــة‬\n‫‪....‬شــرقا‪ :‬بطــول عشــرون متــر ًا يليــه ملــك ‪. ...‬غربــا‪ :‬بطــول اثنــا عشــر‬\n‫متــر ًا يليــه ‪ . ...‬وذلــك بقيمــة إجماليــة مقدارها ثالثــون ألف ريال ‪30,000‬‬\n‫فقــط ال غيــر ريــال ســعودي ‪.‬ثانيــا‪ :‬لقــد قبــل املشــتري الشــراء بالثمــن‬\n‫املذكــور أعــاه بنفــس املواصفــات املذكــورة ‪.‬ثالثــا‪ :‬قــام الطرفــان‬\n‫بالوقــوف علــى العــن املذكــورة وقبــا بهــا بحالتهــا الراهنــة ‪.‬رابعــا ‪:‬‬\n‫يعتبــر هــذا العقــد مبايعــة شــرعية حتــى يتــم تســجيلها لــدى كاتــب‬\n‫عــدل حســب املتبــع وهــو ملــزم لــكال الطرفــن ‪ .‬خامســا ‪ :‬يف حالــة عــدم‬\n‫إلــزام املشــتري بســداد األقســاط يف موعدهــا يحــق للبائــع بيعهــا وإعــادة‬\n‫مــا أســتلم للمشــتري علــى أقســاط شــهرية ا‪.‬ه ـ كمــا أن املدعــى عليــه‬\n‫قــام ببيــع القطعــة األولــى املســماة الصفــى العثــري مببلــغ وقــدره مائتــان‬\n‫ألــف ريــال لشــخص ثانــي اســمه ‪ ...‬بعــد أن باعهــا ملوكلــي وقبــض الثمــن‬\n\n\n                                                                                     ‫‪214‬‬\n\f      ‫منهمــا دليــل ‪ .‬تالعــب وغــش يف البيــع بــل هــو بيــع مــاال ميلــك كمــا نــص‬\n      ‫احلديــث ‪.‬وحيــث أن مــا قــام بــه املدعــى عليــه مخالــف لقواعــد الشــرع‬\n                                       ‫وارتــكاب ملــا نهــى عنــه الشــارع أطلــب اآلتــي‪:‬‬\n      ‫‪ -1‬احلكــم علــى املدعــى عليــه بإلزامــه بإفــراغ جميــع املبيــع مــن عقــارات‬\n      ‫املســاه الظاهــرة الســفلي واحلفــده والصفــى العثــري والتــي مت بيعهــا‬\n        ‫مبوجــب عقــود البيــع املرفقــة وقبــض الثمــن والتهميــش علــى الصــك ‪.‬‬\n      ‫‪ -2‬احلكــم بإلزامــه بأتعــاب وقدرهــا خمســون ألــف ريــال انتهــى وجــرى‬\n      ‫ضمهــا باملعاملــة وزود وكيــل املدعــى عليــه بصــورة منهــا وباطالعــه‬\n      ‫عليهــا طلــب إمهالــه لإلجابــة فأجيــب لطلبــه كمــا جــرى ســؤالهما‬\n      ‫عــن صكــوك امللكيــة وحصــر الورثــة فاســتعد وكيــل املدعــى عليــه‬\n      ‫بإحضارهــا وعليــه رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي ‪...‬‬\n      ‫كمــا حضــر املدعــى عليــه وكالــة ‪...‬املرصــودة وكالتيهمــا ســابقا‬\n      ‫وبســؤال املدعــى عليــه وكالــة عمــا اســتعد بــه أبــرز صــك حصــر الورثــة‬\n      ‫الصــادر مــن هــذه احملكمــة برقــم ‪ 20/46/91‬يف ‪1424/4/2‬ه ـ‬\n      ‫وباالطــاع عليــه وجــد يتضمــن ثبــوت وفــاة ‪...‬بتاريــخ ‪1424/3/3‬ه ـ‬\n      ‫وانحصــار إرثــه يف أوالده ‪...‬و‪...‬و‪ ...‬و‪...‬و‪ ...‬كمــا أبــرز الصــك الصــادر‬\n      ‫مــن محكمــة تنومــة برقــم ‪ ...‬يف ‪1405/10/25‬ه ـ وباالطــاع عليــه‬\n      ‫وجــد يتضمــن قســمة األمــاك العقاريــة ل‪...‬بــن ورثتــه ومهمــش عليــه‬\n      ‫بأنــه جــرى تقســيم مــا بباطــن الصــك بــن ورثــة ‪...‬وهــم ‪ ...‬و‪ ......‬و‪...‬و‪ ...‬و‪...‬‬\n      ‫أوالد ‪...‬وقــد أخرجــت لهــم صكــوك برقــم ‪ ...‬و ‪ ...‬و ‪ ....‬و ‪ ...‬و ‪ ...‬بتاريــخ‬\n      ‫‪1431/11/3‬ه ـ كمــا أبــرز الصــك الصادر من كتابة عدل تنومة برقم‬\n      ‫‪ ...‬يف ‪1431/11/3‬ه ـ وباالطــاع عليــه وجــد يتضمــن ملكيــة ‪ ...‬للقطعــة‬\n      ‫املســماة الصفــي العشــري ويحدهــا مــن الشــمال ملــك ‪...‬بطــول ‪30‬م ومــن‬\n\n\n‫‪215‬‬\n\f‫اجلنــوب ســبيل بطــول ‪30‬م ومــن الغــرب ملــك ‪...‬بطــول ‪21‬م ومــن الشــرق‬\n‫ســبيل بطــول ‪21‬م واملســاحة اإلجماليــة ســتمائة وثالثــون متــرا مربعــا‬\n‫وملكيتــه أيضــا للقطعــة املســماة الظاهــرة الســفلى واحلفــده واحملــدودة‬\n‫شــماال مجــرى ســيل بطــول ‪60‬م وجنوبــا ملــك ‪...‬وملــك ورثــة ‪...‬وســبيل‬\n‫مــاء البئــر بطــول ‪55‬م وشــرقا ملــك ‪...‬بطــول ‪20‬م وغربــا ملــك ‪...‬بطــول‬\n‫‪12‬م واملســاحة اإلجماليــة ألــف وســبعة وعشــرون متــرا مربعــا ومهمــش‬\n‫عليــه بانتقــال ملكيــة القطعــة املســماة الصفــى العثــري إلــى ملــك ‪...‬‬\n‫بثمــن وقــدره مائتــا ألــف ريــال ثــم جــرى ســؤال املدعــى عليــه وكالــة عــن‬\n‫جوابــه علــى الدعــوى فأبــرز مذكــرة مكونــة مــن ورقتــن ونــص احلاجــة‬\n‫منهــا كمــا يلــي ‪ :‬املدعــى عليــه يــرد هــذه الدعــوى لألســباب اآلتيــة‪ :‬أوال‪:‬‬\n‫البيــع باطــل شــرعا ‪ .‬فاملدعــي أقــر يف صحيفــة دعــواه بــأن البيــع مت يف‬\n‫تاريخ‪1427/10/14:‬ه ـ واملدعــى عليــه لــم يكــن ميتلك هاتــن القطعتني‬\n‫يف هــذا التاريــخ لــذا فإننــا أمــام بيــع باطــل شــرعا‪ .‬فــا يجــوز أن يبيــع‬\n‫اإلنســان ســلعة ال ميلكهــا حــال العقــد‪ ،‬حلديــث حكيــم بــن حــزام قــال‪:‬‬\n‫«أتيــت رســول اهلل صلــى اهلل عليــه وســلم فقلــت‪ :‬يأتينــي الرجــل يســألني‬\n‫مــن البيــع مــا ليــس عنــدي‪ ،‬أبتــاع لــه مــن الســوق ثــم أبيعــه؟ قــال‪ « :‬ال تبــع‬\n‫مــا ليــس عنــدك « رواه الترمــذي والنســائي وأحمــد‪ .‬وال يســعنا إلثبــات‬\n‫هــذا األمــر ســوى إرفــاق مــا يثبــت بــان األرض محــل هــذه الدعــوى بقيــت‬\n‫إلــى تاريخ‪1431/11/3:‬ه ـ ملــكا لورثــة ‪...‬وهــم ‪...‬و‪ ...‬و‪ ...‬و‪ ......‬و‪ ...‬أبنــاء‬\n‫‪...‬ولــم تكــن ملــكا مفــرز ًا للمدعــى عليــه وبالتالــي فــإن البيــع الــذي مت‬\n                                      ‫بتاريــخ‪1427/10/ 14‬ه ـ بيــع باطــل شــرعا‪.‬‬\n‫ثانيــا‪ :‬البيــع ورد علــى قطعتــن مفرزتــن واملدعــى عليــه لــم يكــن‬\n‫ميتلكهمــا مفرزتــن وقــت البيــع وإمنــا كانتــا علــى املشــاع بينــه وبــن‬\n\n\n                                                                                            ‫‪216‬‬\n\f      ‫إخوتــه فصحيــح أن بيــع املشــاع جائــز ولكــن هنــاك ثمــة شــروط البــد‬\n      ‫مــن توافرهــا وهــي إجــازة باقــي املــاك علــى الشــيوع وهــم الورثــة وهــم‬\n      ‫لــم يرضــوا بذلــك البيــع وانتهــى األمــر يف حينهــا واملدعــي أصالــة يعلــم‬\n                                                                       ‫ذلــك األمــر يقينــا‪.‬‬\n      ‫ثالثــا‪ :‬البيــع مت تعليقــه علــى شــرط موافقــة باقــي الورثــة واملدعــي أصالــة‬\n      ‫ا ومت إبالغــه‬ ‫يعــي ويعلــم ذلــك علــم اليقــن وباقــي الورثــة لــم يوافقــوا فعـ ً‬\n                                                   ‫بذلــك وتســليمه املبلــغ ورفــض ذلــك‪.‬‬\n      ‫رابعــا‪ :‬يشــهد‪ ... /‬بــأن البيــع لــم يتــم وبحضــور املدعــي ‪ .‬لــذا وبنــاء علــى‬\n      ‫كل مــا تقــدم نلتمــس احلكــم بــرد الدعــوى وإلــزام املدعــي بأتعــاب‬\n      ‫احملامــاة اه ـ ‪ .‬وجــرى ضمهــا مبلــف الدعــوى وزود املدعــي وكالــة‬\n      ‫بصــورة منهــا وباطالعــه عليهــا قــال أكتفــي مبــا ســبق تقدميــه ســابقا‬\n      ‫واطلــب إنهــاء القضيــة هكــذا أجــاب وعليــه رفعــت اجللســة لالستفســار‬\n      ‫عــن ســجلي الصكــن املشــار إليهمــا أعــاه وتأجلــت حتــى ورود اجلــواب‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وقــد وردنــي خطــاب فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بتنومــة رقــم ‪ 1150‬يف ‪1433/10/17‬ه ـ املتضمــن أن‬\n      ‫صــورة الصــك مطابقــة لســجلها وال يوجــد عليهــا أي مالحظــات كمــا‬\n      ‫وردنــي خطــاب فضيلــة كاتــب عــدل تنومــة رقــم ‪ ...‬يف ‪1433/9/3‬ه ـ‬\n      ‫املتضمــن أن الصــك رقــم ‪ ...‬بتاريــخ ‪1431/11/3‬ه ـ مطابــق لســجله وال‬\n      ‫يوجــد عليــه أي مالحظــات ثــم جــرى ســؤال املدعــي وكالــة عــن جوابــه‬\n      ‫علــى مــا ذكــره املدعــى عليــه وكالــة مــن كــون البيــع قــد مت قبــل فــرز‬\n      ‫املبيــع ملوكلــه فأجــاب بقولــه مــا ذكــره ال صحــة لــه والصحيــح أن‬\n      ‫تقســيم نصيــب والــد املدعــى عليــه بــن ورثتــه قــد مت قبــل شــراء موكلــي‬\n      ‫نصيــب املدعــى عليــه إال أن اإلفــراغ قــد تأخــر لغــرض اســتكمال‬\n\n\n‫‪217‬‬\n\f‫اإلجــراءات النظاميــة والكروكيــات وممــا يقــوي ذلــك أن املبيــع هــو‬\n‫نفــس نصيبــه هكــذا أجــاب وبــرد ذلــك علــى املدعــى عليــه وكالــة قــال‬\n‫الصحيــح مــا ذكرتــه وللتأمــل رفعــت اجللســة ويف جلســة أخــرى حضــر‬\n‫املدعــي أصالــة كمــا حضــر املدعــى عليــه وكالــة وملزيــد مــن التحقــق‬\n‫فقــد جــرى ســؤال املدعــى عليــه وكالــة هــل قــام موكلــه ببيــع املدعــي‬\n‫القطــع املذكــورة أم ال فقــال نعــم لقــد باعاهــا عليــه يف عــام ‪1427‬ه ـ‬\n‫ولكنــه اشــترط موافقــة باقــي الورثــة هكــذا أجــاب فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وحيــث تضمنــت املذكــرة اجلوابيــة املقدمــة‬\n‫مــن املدعــى عليــه يف جلســة ســابقة إقــراره بصحــة صــدور البيــع وهــو‬\n‫مــا أكــده يف هــذه اجللســة وأمــا مــا دفــع بــه مــن عــدم ملكيتــه للمبيــع‬\n‫مفــرزا حــن البيــع ال يؤثــر علــى دعــوى املدعــي وال يصــح االحتجــاج بــه‬\n‫وذلــك للقاعــدة املتقــررة بــأن مــن ســعى يف نقــض مــا مت مــن جهتــه فســعيه‬\n‫مــردود عليــه قــال يف الــدر املختــار ( بــاع عبــد غيــره بغيــر إذنــه فبرهــن‬\n‫املشــتري مثــا علــى إقــرار البائــع الفضولــي أو علــى إقــرار رب العبــد أنــه‬\n‫لــم يأمــره بالبيــع للعبــد وأراد املشــتري رد البيــع ردت بينتــه ولــم يقبــل‬\n‫قولــه للتناقــض كمــا لــو أقــام البائــع البينــة أنــه بــاع بــا أمــر أو برهــن‬\n‫علــى إقــرار املشــتري بذلــك وأصلــه أن مــن ســعى نقــض مــا مت مــن جهتــه‬\n‫ال تقبــل )رد احملتــار علــى الــدر املختــار ‪ 328 ، 327/7‬ويقــوي ذلــك‬\n‫مــا انتهــت إليــه القســمة مــن فــرز املبيــع للمدعــى عليــه وحيــث تبــن أن‬\n‫املدعــى عليــه قــام ببيــع جــزء مــن املبيــع وهــي القطعــة املســماة ‪ ...‬علــى ‪...‬‬\n‫ومــن املســتقر قضــاء أن الدعــوى تقــام علــى مــن بيــده العــن لــذا فقــد‬\n‫ثبــت لــدي ملكيــة املدعــي للقطعــة املســماة بالظاهــرة الســفلى واحلفــدة‬\n‫واململوكــة مبوجــب الصــك الصــادر مــن كاتــب عــدل تنومــة رقــم ‪...‬‬\n\n\n                                                                                          ‫‪218‬‬\n\f      ‫يف ‪1431/11/3‬ه ـ وصرفــت النظــر عــن طلبــه إثبــات ملكيتــه للقطعــة‬\n      ‫املســماة ‪ ...‬ومبــا تقــدم حكمــت وأمــرت بالتهميــش علــى صــك امللكيــة‬\n      ‫مبوجبــه بعــد اكتســاب احلكــم القطعيــة وأفهمــت املدعــي بــأن لــه إقامة‬\n      ‫دعــواه فيمــا يخــص القطعــة املســماة ‪ ...‬علــى مــن بيــده العــن وبإعــان‬\n      ‫احلكــم قــرر املدعــي القناعــة بــه وقــرر املدعــى عليــه عدمهــا وطلــب‬\n      ‫االســتئناف بالئحــة فجــرى إفهامــه بــأن عليــه املراجعــة يــوم الثالثــاء‬\n      ‫املوافــق ‪1434/04/09‬ه ـ الســتالم نســخة مــن صــك احلكــم وأن عليــه‬\n      ‫تقــدمي الئحتــه االعتراضيــة خــال ثالثــن يومــا تبــدأ مــن التاريــخ احملــدد‬\n      ‫للمراجعــة وإال فــإن حقــه يف طلــب االســتئناف يســقط ويكتســب‬\n      ‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/06/21‬ه ـ‬\n      ‫لــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة خلــف‬\n      ‫فضيلــة الشــيخ ‪ ...‬بنــاء علــى خطــاب فضيلــة رئيــس احملكمــة رقــم‬\n      ‫‪ 34/1023938‬يف ‪1434/04/27‬ه ـ املبنــي علــى قــرار رئيــس املجلــس‬\n      ‫األعلــى للقضــاء رقــم ‪ 7854‬يف ‪1434/04/23‬ه ـ واملبنــي علــى قــرار‬\n      ‫املجلــس األعلــى للقضــاء رقــم ‪ 1434/1/77‬يف ‪1434/4/13‬ه ـ عليــه‬\n      ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 33446910‬يف ‪1434/06/18‬ه ـ مرفقــا بهــا القــرار رقــم ‪34234860‬‬\n      ‫يف ‪1434/06/10‬ه ـ ونــص احلاجــة منــه ‪ ( :‬وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل‬\n      ‫املوفــق قاضــي اســتئناف ‪...‬توقيعــه وختمــه قاضــي اســتئناف ‪...‬توقيعــه‬\n      ‫وختمــه رئيــس الدائــرة ‪...‬توقيعــه وختمــه ) لــذا جــرى حتريــره حتــى‬\n\n\n‫‪219‬‬\n\f‫ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                             ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/21‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪ 33446910‬وتاريــخ ‪1434/5/22‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة العامــة مبكة املكرمة واملســجل‬\n‫بعــدد ‪ 34179277‬وتاريــخ ‪1434/4/6‬ه ـ واملتضمــن دعــوى‪... /‬ضــد‪/‬‬\n                                       ‫‪...‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                        ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":210,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"de9984c7a89b5ba0a6400051dcd073f6943a3c10224f7e9599bed63d7c58c34c","normalized_text_hash":"febb0a29c83a6fabd38b1791d9392d5029e45075b0df1873e47d9732a95ee410","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p210-34179277"},{"id":"21339ed8-8f42-5f83-8ff6-6256df1f45f7","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء قطعة أرض -طلب اإللزام بإفراغ قطعة أرض - شطب الدعوى لعدم حضور املدعي -تدخل طرف ثالث يف الدعوى -الدفع بأن سبب عدم اإلفراغ هو إيقاف الصك -البيع املعلق على شرط ال يصح -احلكم ببطان البيع .","document_number":"34192240","case_number":"33121374","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"بيع -عقار -شراء قطعة أرض -طلب اإللزام بإفراغ قطعة أرض - شطب الدعوى لعدم حضور املدعي -تدخل طرف ثالث يف الدعوى -الدفع بأن سبب عدم اإلفراغ هو إيقاف الصك -البيع املعلق على شرط ال يصح -احلكم ببطان البيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/20 :‬هـ‬\n                      ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34192240 :‬‬\n                          ‫َر ْق ُم الدعوى‪33121374 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3423864‬تاريخه‪1434/6/10 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــار ‪ -‬شــراء قطعــة أرض ‪ -‬طلــب اإللــزام بإفــراغ قطعــة أرض ‪-‬‬\n      ‫شــطب الدعــوى لعــدم حضــور املدعــي ‪ -‬تدخــل طــرف ثالــث يف الدعــوى‬\n      ‫‪ -‬الدفــع بــأن ســبب عــدم اإلفــراغ هــو إيقــاف الصــك ‪ -‬البيــع املعلــق‬\n                              ‫علــى شــرط ال يصــح ‪ -‬احلكــم ببطــان البيــع ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا ذكــره الفقهــاء رحمهــم اهلل تعالــى مــن أن ( البيــع املعلــق علــى‬\n                                                                  ‫شــرط ال يصــح )‬\n                                  ‫‪ -2‬املادة ‪ 53‬و ‪ 55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة بــأن موكلــه اشــتري مــن املدعــى عليــه قطعــة‬\n      ‫أرض ( ذكــر وصفهــا ) مببلــغ مائــه وخمســة وعشــرين ألــف ريــال ســدد‬\n      ‫منهــا موكلــه خمســة وســبعني ألــف ريــال والباقــي خمســون ألــف ريــال‬\n      ‫تســلم عنــد اإلفــراغ ‪ ،‬طلــب املدعــي وكالــة إلــزام املدعــى عليــه بــأن‬\n      ‫يفــرغ ملوكلــه األرض موضــع الدعــوى ‪ ،‬حضــر املدعــى عليــه أصالــة‬\n      ‫وصــادق علــى الدعــوى ودفــع بــأن املبلــغ الــذي اســتلمه مــن املدعــي أصالــة‬\n      ‫خمســن ألــف ريــال وأن ســبب عــدم اإلفــراغ هــو إيقــاف الصــك بأمــر‬\n      ‫احملكمــة ‪ ،‬وأنــه حصــل بينــه وبــن املدعــي أصالــة اتفــاق علــى إعــادة‬\n\n‫‪221‬‬\n\f‫هــذا املبلــغ اخلمســن ألــف ريــال وقــد أعادهــا بالكامــل كمــا دفــع‬\n‫خمســة آالف ريــال للمدعــي وكالــة قيمــة األتعــاب وطلــب رد الدعــوى‬\n‫‪ ،‬صــادق املدعــي وكالــة علــى مــا ذكــره املدعــى عليــه وذكــر بــأن‬\n‫املدعــى عليــه شــرط علــى نفســه أنــه متــى انتهــت اإلشــكاليات علــى‬\n‫هــذه األرض فإنــه ســيقوم بإفراغهــا ملوكلــه وأن موكلــه ســيقوم بدفــع‬\n‫مائــة وخمســة وعشــرين ألــف ريــال ‪ ،‬صــادق املدعــى عليــه علــى هــذا‬\n‫الشــرط ‪ ،‬ملــا ذكــره الفقهــاء مــن أن البيــع املعلــق علــى شــرط ال يصــح‬\n‫لــذا صــدر احلكــم ببطــان البيــع احلاصــل بينهمــا واعتبــار القضيــة‬\n‫منتهيــة بخصــوص موضــوع الدعــوى وأن الشــرط احلاصــل بينهمــا وهــو‬\n‫قيــام املدعــى عليــه باإلفــراغ للمدعــى أصالــة اذا انتهــت اإلشــكاليات‬\n‫فهــذا شــرط باطــل ‪ ،‬اعتــرض املدعــي وكالــة علــى احلكــم ‪ ،‬صــدق‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائف‪/‬املكلــف برقــم ‪ 33121374‬وتاريــخ ‪ 1433/2/16‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33317704‬وتاريــخ ‪1433/2/16‬ه ـ املتعلقــة‬\n‫بدعــوى ‪...‬ضــد ‪...‬يف دعــوى يف ملكيــة عقــار أو غيــره ويف يــوم االثنــن‬\n‫‪ 1433/5/17‬ه ـ افتتحــت اجللســة يف متــام الســاعة العاشــرة صباحــا‬\n‫وجــرى النــداء علــى املدعــي واملدعــى عليــه فلــم يحضــر منهمــا أحــد ولــم‬\n‫يقدمــا عــذر لتخلفهمــا عــن هــذه اجللســة ولــم يتقــدم وكيل عــن اي منهما‬\n‫وقــد حــدد لهمــا موعــد يف هــذا اليــوم يف متــام الســاعة التاســعة والنصــف‬\n\n                                                                                   ‫‪222‬‬\n\f      ‫صباحــا وجــرى النــداء واالنتظــار مــن بدايــة وقــت اجللســة وحتــى انتهــاء‬\n      ‫وقتهــا فلــم يحضــر أحــد وقــد مت بعــث تبليــغ للمدعــى عليــه عــن طريــق‬\n      ‫محضــري اخلصــوم بهــذه احملكمــة ولــم يردنــا مــا يفيــد بتبليــغ املدعــى‬\n      ‫عليــه مــن عدمــه فعليــه وبنــاء علــى املــادة (‪ )53‬مــن نظــام املرافعــات‬\n      ‫الشــرعية فقــد أمــرت بشــطب هــذه القضيــة للمــرة االولــى وال تنظــر اال‬\n      ‫بعــذر يتقــدم بــه املدعــي أو وكيــل عنــه وتقبلــه احملكمــة وأمــرت بحفظ‬\n      ‫هــذه الدعــوى يف االرشــيف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/4/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االحــد ‪1433/10/15‬ه ـ افتتحــت‬\n      ‫اجللســة يف متــام الســاعة التاســعة صباحــا وفيهــا حضــر ‪...‬يحمــل بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪...‬حالــة كونــه وكيــل عــن املدعــي ‪...‬يحمــل ســجل‬\n      ‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الطائــف الثانيــة‬\n      ‫برقــم ‪ 18825‬يف ‪1425/05/12‬ه ـ اجللــد ‪ 1426‬والتــي تخولــه يف إقامــة‬\n      ‫وســماع عمــوم الدعــاوي واملطالبــات املقامــة منــه أو ضــده أمــام أي‬\n      ‫محكمــة واملدافعــة واملرافعــة وحضــور اجللســات وتقدمي البينــات االقرار‬\n      ‫واالنــكار وتقــدمي لوائــح االدعــاء واالعتــراض واحضــار الشــهود وطلــب‬\n      ‫االميــان واجلــرح والتعديــل والتوقيــع ولــم يحضــر املدعــى عليــه ‪...‬وقــد مت‬\n      ‫تبليغــه مبوعــد هــذه اجللســة حيــث مت بعــث تبليــغ لــه عــن طريــق محضــري‬\n      ‫اخلصــوم بهــذه احملكمــة برقــم ‪ 331082601‬يف ‪1433/06/08‬ه ـ‬\n      ‫وقــد أفادنــا مديــر مركــز شــرطة النزهــة بخطابــه رقــم ‪/2251‬ع يف‬\n      ‫‪1433/07/14‬ه ـ املتضمــن أنــه قــد مت إبــاغ املدعــى عليــه هــذا كمــا‬\n      ‫جــرى االطــاع علــى املعاملــة فوجــدت ورقــة تبليــغ واملتضمــن بــأن املدعــى‬\n      ‫عليــه قــد تبلــغ باملوعــد احملــدد يف يــوم االثنــن ‪1433/05/17‬ه ـ وذلــك‬\n\n\n‫‪223‬‬\n\f‫عــن طريــق احملضــر يف هــذه احملكمــة ‪ ...‬فعليــه وبنــاء علــى املــادة‬\n‫اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية فقــد قــررت ســماع‬\n‫دعــوى املدعــي يف غيــاب املدعــى عليــه وجــرى ســؤال املدعــي بالوكالــة‬\n‫عــن دعــوى موكلــه فقــال إن موكلــي قــد اشــترى مــن املدعــى عليــه‬\n‫الغائــب عــن املجلــس الشــرعي ‪...‬القطعــة رقــم (‪ )571‬يف ‪1430/7/18‬ه ـ‬\n‫والواقعة مبخطط ‪ ...‬يف حي ‪ ...‬واحملدودة شــماال بشــارع وجنوبا القطعة‬\n‫رقــم (‪ )552‬وشــرقا القطعــة رقــم (‪ )572‬وغربــا القطعــة رقــم (‪)570‬‬\n‫واملســاحة االجماليــة ســتمائة وعشــرين متــرا مربعــا مببلــغ مائــة وخمســة‬\n‫وعشــرين الــف ريــال ســدد منهــا موكلــي للمدعــى عليــه مبلــغ خمســة‬\n‫وســبعني الــف ريــال والباقــي وهــو مبلــغ خمســون الــف ريــال عنــد االفــراغ‬\n‫وحتــى هــذا اليــوم واملدعــى عليــه لــم يفــرغ ملوكلــي لــذا فموكلــي يطلــب‬\n‫إلــزام املدعــى عليــه ‪...‬بــأن يفــرغ لنــا االرض هــذه دعــواي فجــرى ســؤاله‬\n‫هــل لديــك البينــة علــى صحــة دعــواك فقــال نعــم ثــم أبــرز ورقــة صــادرة‬\n‫مــن مؤسســة ‪...‬للتجــارة مؤرخــة يف ‪1430/07/18‬ه ـ واملتضمنــة مــا‬\n‫نصهــا (عقــد بيــع ابتدائــي طــرف أول ‪...‬طــرف ثانــي ‪...‬بــاع الطــرف االول‬\n‫علــى الطــرف الثانــي القطعــة رقــم (‪ )571‬مــن مخطــط ‪ ...‬مخطــط ‪...‬‬\n‫العــام مببلــغ مائــة وخمســة وعشــرين الــف ريــال طــرف أول توقيعــه طــرف‬\n‫ثانــي توقيعــه) اه ـ ‪ .‬فجــرى ســؤاله هــل لديــك زيــادة بينــة قــال ليــس لــدي‬\n‫ســوى مــا ذكــرت هكــذا قــرر ثــم رفعــت اجللســة إلحضــار املدعــى عليــه‬\n‫وحتــى يــوم الســبت ‪1434/01/10‬ه ـ الســاعة العاشــرة صباحــا وأفهــم‬\n‫املدعــي بالوكالــة باملوعــد وبإحضــار وكالــة جديــدة ففهــم ذلــك وعليــه‬\n‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم حــرر يف ‪ 1433/10/15‬ه ـ‬\n\n\n                                                                                      ‫‪224‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬رئيــس احملكمــة العامــة بالطائــف‪/‬‬\n      ‫املســاعد والقائــم بعمــل املكتــب القضائــي الســادس ويف هــذا اليــوم‬\n      ‫الســبت‪1434/01/10‬هـ افتتحــت اجللســة يف متــام الســاعة العاشــرة‬\n      ‫صباحــا وفيهــا حضــر املدعــي وكالــة ‪...‬املدونــة هويتــه ووكالتــه ســابقا‬\n      ‫كمــا حضــر ‪ ...‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪...‬بصفتــه الوكيــل‬\n      ‫الشــرعي عــن املدعــى عليــه ‪...‬يحمــل ســجل مدنــي رقــم ‪...‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل الطائــف الثانيــة برقــم ‪42153‬‬\n      ‫يف ‪1429/08/18‬ه ـ اجللــد ‪ 3599‬والتــي تخولــه إقامــة وســماع عمــوم‬\n      ‫الــداوي واملدافعــة واملرافعــة وحضــور اجللســات وتقــدمي البنــات واالقــرار‬\n      ‫واالنــكار وتقــدمي لوائــح االدعــاء واالعتراض وإحضار الشــهود والتوقيع‬\n      ‫وحضــر املتداخــل يف هــذه الدعــوى ‪...‬يحمــل بطاقــة الهويــة الوطنيــة رقــم‬\n      ‫‪...‬املتقــدم باســتدعائه املقيــد بهــذه احملكمــة برقــم ‪ 33/1988431‬يف‬\n      ‫‪1433/11/10‬ه ـ املرفــق باملعاملــة فجــرى ســؤال املدعــى فجــرى ســؤال‬\n      ‫املدعــي بالوكالــة هــل أحضــرت مــا طلــب منــك يف اجللســة املاضيــة مــن‬\n      ‫إحضــار وكالــة جديــد فقــال لــم أســتطع إحضــار الوكالــة حيــث أن‬\n      ‫املدعــي أصالــة مســجون االن مبرجعــه يف مطالبــه بحقــوق ماليــة وأطلــب‬\n      ‫املهلــة حتــى أمتكــن مــن إحضــار الوكالــة هكــذا أجــاب وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه بالوكالــة واملتداخــل اجابــا جميعــا ال مانــع لدينــا‬\n      ‫مــن إعطائــه مهلــة هكــذا أجابــا فعليــه فقــد أجبتهــم لطلبهــم ثــم رفعــت‬\n      ‫اجللســة يف متــام الســاعة العاشــرة وعشــرين دقيقــة صباحــا وحتــى يــوم‬\n      ‫الســبت ‪1434/04/20‬ه ـ الســاعة العاشــرة صباحــا وأفهــم اجلميــع‬\n      ‫باملوعــد وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/01/10‬ه ـ‬\n\n\n‫‪225‬‬\n\f‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ويف هــذا اليــوم الســبت‪1434/04/20‬هـ افتتحــت اجللســة يف‬\n‫متــام الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي وكالــة ‪...‬املدونــة‬\n‫هويتــه ووكالتــه ســابقا كمــا حضــر حلضــوره املدعــى عليــه ‪...‬يحمــل‬\n‫بطاقــة الهويــة الوطنيــة رقــم ‪...‬ولــم يحضــر املتداخــل ‪...‬مــع تبلغــه مبوعــد‬\n‫هــذه اجللســة يف اجللســة املاضيــة وبعــرض دعــوى املدعــي بالوكالــة علــى‬\n‫املدعــى عليــه أصالــة قــال كل مــا ذكــره املدعــي بالوكالــة يف دعــواه‬\n‫مــن أن موكلــه قــد اشــترى منــي القطعــة املوصوفــة يف دعــواه وباملبلــغ‬\n‫الــذي ذكــر فهــذا كلــه صحيــح وأمــا مــا ذكــره مــن أن موكلــه قــد‬\n‫ســدد مــن قيمتهــا مبلــغ خمســة وســبعني الــف ريــال فليــس بصحيــح‬\n‫والصحيــح بأننــي قــد اســتلمت مــن موكلــه مبلــغ خمســن ألــف ريــال‬\n‫وال اســتطيع افــراغ االرض حيــث أنهــا موقفــة بأمــر مــن احملكمــة وقــد‬\n‫حصــل بينــي وبــن مــوكل املدعــي هــذا احلاضــر علــى ان اعيــد املبلــغ‬\n‫الــذي دفــع وهــو مبلــغ خمســن الــف ريــال وقــد دفعتهــا كاملــة واعــدت‬\n‫لهــم املبلــغ كمــا اشــترط علــي بــأن ادفــع لهــم مبلــغ خمســة آالف ريــال‬\n‫للمدعــي بالوكالــة قيمــة االتعــاب وقــد دفعتهــا لهــذا احلاضــر ولــذا اطلب‬\n‫رد عــوى املدعــي هكــذا أجــاب وبعــرض ذلــك علــى املدعــي بالوكالــة‬\n‫أجــاب قائــا كل مــا ذكــره املدعــى عليــه مــن اســتالمه مبلــغ خمســن‬\n‫الــف ريــال قيمــة االرض وقــد أعادهــا ملوكلــي كمــا أنــه قــد دفــع لــي‬\n‫مبلــغ خمســة آالف ريــال قيمــة االتعــاب فهــذا كلــه صحيــح ومــا ذكــره‬\n‫مــن أن االرض موقوفــة فهــذا صحيــح وعليهــا اشــكاليات وهــي يف‬\n‫هــذه احملكمــة وقــد اســتلمنا مــا ســلمناه للمدعــى عليــه وبقــي هنــاك‬\n‫شــرط حيــث أن املدعــى عليــه قــد شــرط علــى نفســه أنــه متــى انتهــت‬\n\n\n                                                                                      ‫‪226‬‬\n\f      ‫االشــكاليات علــى هــذه االرض فســيقوم املدعــى عليــه بإفــراغ هــذه‬\n      ‫االرض ملوكلــي وســيقوم موكلــي بدفــع مبلــغ مائــة وخمســة وعشــرين‬\n      ‫ألــف ريــال قيمــة هــذه االرض هكــذا قــرر وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه قــال كل مــا ذكــره مــن أن هنــاك شــرط فهــذا صحيــح وال مانــع‬\n      ‫لــدي مــن إفــراغ االرض ملوكلــه اذا انتهــت مــن االشــكاليات واصبحــت‬\n      ‫ملــك لــي وســأفراغها مببلــغ مائــة وخمســة وعشــرين ألــف ريــال هكــذا‬\n      ‫قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وملصادقــة املدعــي علــى‬\n      ‫مــا ذكــره املدعــى عليــه مــن اســتالم موكلــه قيمــة االرض وهــو مبلــغ‬\n      ‫خمســن الــف ريــال وكذلــك اقــرار الوكيــل باســتالمه مبلــغ خمســة‬\n      ‫آالف ريــال وملصادقتــه بــأن االرض موقفــة لــدى احملكمــة وفيهــا‬\n      ‫اشــكاليات وال عــذر ملــن اقــر وأمــا بالنســبة ملــا شــرطه املدعــي علــى‬\n      ‫املدعــى عليــه مــن أن االرض إذا حتــررت واصبحــت ملــك للمدعــى عليــه‬\n      ‫فســيفرغها لهــم مببلــغ مائــة وخمســة وعشــرين الــف ريــال وقــد ذكــر‬\n      ‫االصحــاب رحمهــم اهلل تعالــى مــا نصــه (البيــع املعلــق علــى شــرط ال‬\n      ‫يصــح ) اه ـ ‪ .‬جلميــع ذلــك فقــد ألزمــت باآلتــي أوال ببطــان البيــع احلاصــل‬\n      ‫بينهمــا ثانيــا اعتبــرت القضيــة منتهيــة بخصــوص موضــوع هــذه الدعــوى‬\n      ‫ثالثــا الشــرط احلاصــل بينهمــا وهــو قيــام املدعــى عليــه باالفــراغ للمدعــي‬\n      ‫أصالــة هــذه القطعــة اذا انتهــت مــن االشــكاليات فهــذا الشــرط باطــل‬\n      ‫وبــه حكمــت وبعرضــه عليهمــا لــم يقنــع بــه املدعــي بالوكالــة واســتعد‬\n      ‫بتقــدمي الئحــة اعتراضيــة فجــرى تســليمه صــورة مــن احلكــم وافهــم بــأن‬\n      ‫لــه مهلــة ثالثــن يومــا لتقــدمي اعتراضــه عليــه واذا انتهــت هــذه املهلــة ولــم‬\n      ‫يتقــدم باعتراضــه فسيســقط حقــه يف االعتــراض ويف طلــب االســتئناف‬\n      ‫ويكتســب احلكــم القطعيــة ويصبــح واجــب التنفيــذ وبعرضــه علــى‬\n\n\n‫‪227‬‬\n\f‫املدعــى عليــه قنــع بــه وأمــرت بإصــدار صــك مبوجبه وعليه جــرى التوقيع‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫حــرر يف ‪1434/04/20‬ه ـ الســاعة العاشــرة وخمســة واربعــن دقيقــة ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي باحملكمــة العامــة بالطائــف‬\n‫واخللــف لفضيلــة الشــيخ ‪...‬ويف هــذا اليــوم الســبت ‪1434/06/24‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الثامنــة وخمســة واربعــن دقيقــة‬\n‫وفيهــا وردت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫‪ 33317704‬يف ‪1434/06/13‬ه ـ وقــد جــرى تدقيــق احلكــم مــن الدائرة‬\n‫احلقوقيــة االولــى مبحكمــة االســتئناف وصــدر بشــأنه القــرار رقــم‬\n‫‪ 34234864‬يف ‪1434/06/10‬ه ـ املــدون علــى ظهــر الصــك واملتضمــن‬\n‫(احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪34192240‬‬\n‫وتاريــخ ‪1434/04/20‬ه ـ الصــادر مــن فضيلة الشــيخ ‪ ...‬واصدرنا القرار‬\n‫رقــم ‪ 34234864‬وتاريــخ ‪1434/06/10‬ه ـ املتضمــن املوافقــة علــى‬\n‫احلكــم واهلل املوفــق عضــو ‪...‬ختمــه وتوقيعــه عضــو ‪ ...‬ختمــه وتوقيعــه‬\n‫رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه) اه ـ ‪ .‬وعليــه فقــد أمــرت بإحلــاق ذلــك‬\n‫بضبطــه وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم حــرر يف‪1434/06/24‬ه ـ الســاعة التاســعة صباحــا ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪ 33/317704‬وتاريــخ‬\n‫‪1434/5/25‬هـ املرفق بها الصك الصادر من فضيلة الشــيخ ‪...‬القاضي‬\n‫باحملكمــة العامــة بالطائــف ســابق ًا واملســجل بعــدد ‪ 34192240‬وتاريــخ‬\n\n\n                                                                                   ‫‪228‬‬\n\f      ‫‪1434/4/20‬هـ ـ واملتضمــن دعــوى ‪ ...‬ضــد ‪ ...‬واحملكــوم فيــه مبــا دون‬\n                                                                            ‫باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                              ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪229‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":221,"source_page_end":229,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fd2f74b27483f1b954a1030ebb237f36ef0a568373c36baef579e81d9bca3836","normalized_text_hash":"06053c074da5b8f6824bcf5def522d37d27abced70e8b133a12c2e4e92c33004","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p221-34192240"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

